const folded=new Map();
const reserved=/^(?:CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(?:\.|$)/i;
for(const relative of files){
  assert.match(relative,/^[\x20-\x7e]+$/,`non-ASCII release path: ${relative}`);
