          <footer><button type="button" disabled={busy} onClick={()=>setActionDialog(undefined)}>Отмена</button>{actionDialog.kind!=='blocked'&&<button type="button" className={actionDialog.kind==='delete'?'danger':'primary'} disabled={busy} onClick={confirmAction}>{busy?<RefreshCw className="spin"/>:actionDialog.kind==='start'?<Play/>:<Trash2/>}{actionDialog.kind==='start'?`Запустить на ${printerDisplayName(printer)}`:'Удалить файл'}</button>}{actionDialog.kind==='blocked'&&<>{onSettings&&<button type="button" onClick={()=>{setActionDialog(undefined);onSettings()}}><SlidersHorizontal/>Настройки принтера</button>}<button type="button" className="primary" onClick={()=>setActionDialog(undefined)}>Понятно</button></>}</footer>
        </section>
      </div>}
      </>}
    </section>
  </div>;
}

