    <section className="setupSection"><header><Check/><div><h3>Характеристики</h3><p>Ручные поправки не стирают распознанную модель.</p></div></header><div className="setupFields four"><label className="field"><span>Стол X, мм</span><input type="number" value={p.bedX} onChange={e=>patch({bedX:+e.target.value})}/></label><label className="field"><span>Стол Y, мм</span><input type="number" value={p.bedY} onChange={e=>patch({bedY:+e.target.value})}/></label><label className="field"><span>Высота Z, мм</span><input type="number" value={p.maxZ} onChange={e=>patch({maxZ:+e.target.value})}/></label><label className="field"><span>Сопло, мм</span><input type="number" step="0.1" value={p.nozzle} onChange={e=>patch({nozzle:+e.target.value})}/></label><label className="field wide"><span>Материалы</span><input value={p.materials.join(', ')} onChange={e=>patch({materials:e.target.value.split(',').map(x=>x.trim().toUpperCase()).filter(Boolean)})}/></label><label className="checkField"><input type="checkbox" checked={!!p.enclosed} onChange={e=>patch({enclosed:e.target.checked})}/><span>Закрытая камера корпуса</span></label><label className="field"><span>Приоритет</span><input type="number" value={p.priority??0} onChange={e=>patch({priority:+e.target.value})}/></label></div></section>
    <section className={`setupSection cameraCapability ${preset==='flashforge-ad5m'?'disabled':''}`}><header><Camera/><div><h3>Камера</h3><p>{model?.camera||'Используются камеры, настроенные в Moonraker.'}</p></div><b>{preset==='flashforge-ad5m'?'НЕТ':preset==='creality-k1-max'||preset==='creality-k1c-2025'?'ШТАТНАЯ':'MOONRAKER'}</b></header></section>
   </div>
  </div>
  {formError&&<div className="printerSetupError"><TriangleAlert/>{formError}</div>}
  <div className="printerSetupActions"><button type="button" disabled={saving||detecting||reattesting||credentialBusy} className="danger printerSetupDelete" onClick={()=>void onDelete()}><Trash2/> Удалить принтер</button><button disabled={saving||detecting||reattesting||credentialBusy} onClick={close}>Отмена</button><button disabled={saving||detecting||reattesting||credentialBusy} className="primary" onClick={save}><Check/> {saving?'Сохранение…':'Сохранить настройки'}</button></div>
 </section></div>
}

import { useEffect, useRef, useState } from 'react';
import { CheckCircle2, Database, LoaderCircle, Printer, ShieldCheck, TriangleAlert, Wifi } from 'lucide-react';
import type { PrinterConfig } from '../types';
import { LanguageSelect, useI18n } from '../i18n';
import appIcon from '../assets/app-icon-v1144.png';
import { MoonrakerClient, type PrinterDetection } from '../lib/moonraker';
import { iconForPreset, profileForPreset } from '../lib/printerProfile';
import { applyModelDetection } from '../lib/modelSelection';
import { applyCatalogModel } from '../lib/printerCatalogSelection';
import { appConfirm } from '../lib/appDialogs';
