type ApiKeyValidation={valid:boolean;protocol:'rest'|'websocket';port:number;message:string};

const normalizeHost=(value:string)=>value.trim().replace(/^http:\/\//i,'').replace(/\/$/,'');
const friendlyError=(error:unknown)=>{
 const text=String(error instanceof Error?error.message:error).toLowerCase();
 if(text.includes('401')||text.includes('403')||text.includes('unauthorized')||text.includes('api key'))return 'Moonraker требует API Key. Введите ключ и повторите проверку.';
 if(text.includes('resolve')||text.includes('invalid')||text.includes('address'))return 'Адрес не распознан. Используйте формат 192.168.1.50:7125.';
 if(text.includes('timeout')||text.includes('connect')||text.includes('refused'))return 'Moonraker не отвечает. Проверьте IP, порты 80/7125 и подключение к одной сети.';
 return `Не удалось проверить Moonraker: ${String(error instanceof Error?error.message:error)}`;
};
const confidenceText=(value:PrinterDetection['confidence'])=>value==='high'?'высокая':value==='medium'?'средняя':value==='low'?'низкая':'недостаточно данных';

export function SetupWizard({onFinish,onAdd}:{onFinish:()=>void;onAdd:(cfg:PrinterConfig)=>void|Promise<void>}){
 const {t}=useI18n();
 const [step,setStep]=useState(0),[host,setHost]=useState(''),[name,setName]=useState(''),[apiKey,setApiKey]=useState('');
 const [automaticName,setAutomaticName]=useState('');
 const [catalogModelId,setCatalogModelId]=useState<string>(),[choosingModel,setChoosingModel]=useState(true),[adding,setAdding]=useState(false);
 const requestGeneration=useRef(0),nameRevision=useRef(0);
 useEffect(()=>()=>{requestGeneration.current++},[]);
 const [checking,setChecking]=useState(false),[detected,setDetected]=useState<PrinterDetection>(),[error,setError]=useState('');
 const catalog=getCatalogModel(catalogModelId);
 const invalidateVerification=()=>{requestGeneration.current++;setDetected(undefined);setChecking(false);setError('')};
 const chooseModel=(entry?:PrinterCatalogModel)=>{
  invalidateVerification();setCatalogModelId(entry?.id);setChoosingModel(false);
  if(!name.trim()||name===automaticName){const next=entry?catalogModelName(entry):'';setName(next);setAutomaticName(next)}
 };
 const finish=()=>{localStorage.setItem('klipper-setup-v07','done');onFinish()};
 const verify=async()=>{
  const normalized=normalizeHost(host);if(!normalized){setError('Введите IP-адрес и порт Moonraker.');return}
  const generation=++requestGeneration.current,nameVersion=nameRevision.current;
  setChecking(true);setDetected(undefined);setError('');
  try{
   const key=apiKey.trim();
   if(key){const validation=await secureInvoke<ApiKeyValidation>('validate_moonraker_api_key',{host:normalized,apiKey:key});if(generation!==requestGeneration.current)return;if(!validation.valid)throw new Error(validation.message||'Moonraker отклонил API Key')}
   const result=await new MoonrakerClient({id:'setup-check',name:name.trim()||'Klipper Printer',host:normalized,apiKey:key||undefined}).detect();
   if(generation!==requestGeneration.current)return;
   setHost(normalized);setDetected(result);
   if(nameVersion===nameRevision.current&&!catalog&&(!name.trim()||name===automaticName)&&result.decision==='confirmed'&&result.model!=='custom'){setName(result.name);setAutomaticName(result.name)}
  }catch(e){if(generation===requestGeneration.current)setError(friendlyError(e))}finally{if(generation===requestGeneration.current)setChecking(false)}
 };
 const add=async()=>{
  if(!detected?.reachable||adding)return;
  const generation=requestGeneration.current;setAdding(true);
  try{
   let confirmProbable=false;
   if(detected.decision==='probable'&&detected.model!=='custom')confirmProbable=await appConfirm(`Программа предполагает модель «${detected.name}», но уверенность средняя. Применить этот профиль? Без подтверждения будет сохранён безопасный универсальный профиль.`,{title:'Подтверждение модели',confirmLabel:'Да, применить профиль'});
   if(generation!==requestGeneration.current)return;
   const base:PrinterConfig={id:crypto.randomUUID(),name:name.trim()||(catalog?catalogModelName(catalog):detected.name),nameSource:!name.trim()||name===automaticName?'automatic':'custom',host:normalizeHost(host),catalogModelId:catalog?.id,apiKey:apiKey.trim()||undefined,icon:iconForPreset('custom'),profile:profileForPreset('custom'),modelSelection:{mode:'automatic',selectedPreset:'custom',source:'automatic'}};
   const configured=applyModelDetection(base,detected,confirmProbable);
   await onAdd(catalog?applyCatalogModel(configured,catalog):configured);if(generation===requestGeneration.current)setStep(2);
  }catch(e){if(generation===requestGeneration.current)setError(String(e instanceof Error?e.message:e))}finally{if(generation===requestGeneration.current)setAdding(false)}
 };
 return <div className={`wizard ${step===1?catalogStyles.wizardCatalog:''}`}><section className="wizardShell">
  <aside className="wizardAside"><img src={appIcon} alt="Klipper Farm"/><h1>Klipper Farm</h1><p>Локальный центр управления вашей фермой 3D‑принтеров.</p><div className="wizardSteps">{['Добро пожаловать','Подключение','Готово'].map((x,i)=><div key={x} className={i===step?'active':i<step?'done':''}><span>{i<step?'✓':i+1}</span><b>{x}</b></div>)}</div><small>Версия 1.14.5 · Transactional Core V13</small></aside>
  <main className="wizardMain"><header><div><span>ПЕРВЫЙ ЗАПУСК</span><b>Шаг {step+1} из 3</b></div><LanguageSelect compact/></header>
   {step===0&&<div className="wizardPage"><div className="wizardHeroIcon"><ShieldCheck/></div><h2>{t('setupIntro')}</h2><p>{t('setupIntroText')}</p><div className="wizardBenefits"><div><Wifi/><b>Локальная сеть</b><span>Без облачного аккаунта</span></div><div><Printer/><b>Несколько принтеров</b><span>Единая панель фермы</span></div><div><Database/><b>Данные на компьютере</b><span>История и настройки локально</span></div></div><button className="primary wizardNext" onClick={()=>setStep(1)}>{t('start')} →</button></div>}
   {step===1&&<div className="wizardPage wizardConnect">
    {choosingModel?<>
     <PrinterModelPicker selectedId={catalogModelId} onSelect={chooseModel} compact/>
     <div className="wizardActions"><button onClick={()=>{invalidateVerification();setStep(2)}}>{t('skip')}</button><button className="primary" onClick={()=>setChoosingModel(false)}>Продолжить {catalog?'с выбранной моделью':'с автоопределением'} →</button></div>
    </>:<>
     <div className="wizardHeroIcon"><Wifi/></div><h2>Подключите первый принтер</h2>
     <p>{catalog?catalogModelName(catalog):'Автоматическое определение модели'} · {catalog?catalogConnectionHint(catalog):'Требуется доступный Klipper/Moonraker'}</p>
     <button type="button" disabled={adding} onClick={()=>{invalidateVerification();setChoosingModel(true)}}>Выбрать другую модель</button>
     <p>{t('hostHelp')} Для K1C можно указать только IP — приложение проверит WebSocket на портах 80 и 7125.</p>
     <label>Название принтера<input disabled={adding} value={name} onChange={e=>{nameRevision.current++;setAutomaticName('');setName(e.target.value)}} placeholder="Определится автоматически"/></label>
     <label>Адрес Moonraker<input disabled={adding} value={host} onChange={e=>{setHost(e.target.value);invalidateVerification()}} placeholder="192.168.1.109 или 192.168.1.109:7125"/></label>
     <label>API Key — если включена авторизация<input disabled={adding} type="password" value={apiKey} onChange={e=>{setApiKey(e.target.value);invalidateVerification()}} placeholder="Можно оставить пустым"/></label>
     <small>Для поддерживаемой выбранной модели применяется её рабочий профиль. Проверка подключения уточняет доступные функции.</small>
     {checking&&<div className="wizardCheck checking"><LoaderCircle/> Проверяем Moonraker, конфигурацию и цифровой отпечаток…</div>}
     {detected&&<div className={`wizardCheck ${detected.ready?'ok':'warn'}`}><CheckCircle2/><div>
      <b>{detected.ready?'Подключение работает':'Moonraker доступен — Klipper ещё не готов'}</b>
      <span>{detected.status!=='matched'||detected.model==='custom'?detected.status==='ambiguous'?'Модель неоднозначна — будет сохранён безопасный пользовательский профиль':'Надёжная модель не определена — будет сохранён пользовательский профиль':`${detected.name} · уверенность: ${confidenceText(detected.confidence)} · ${detected.score} баллов`} · Klipper: {detected.klippyState} · {detected.latency} мс · проверок {detected.probeCoverage.successful}/{detected.probeCoverage.total}</span>
      {detected.probeWarnings.length>0&&<small>Неполный снимок: {detected.probeWarnings.join(', ')}. Принтер можно добавить — проверка повторится автоматически.</small>}
     </div></div>}
     {error&&<div className="wizardCheck error"><TriangleAlert/><span>{error}</span></div>}
     <div className="wizardActions"><button disabled={adding} onClick={()=>{invalidateVerification();setStep(2)}}>{t('skip')}</button><div>
      <button disabled={checking||adding||!host.trim()} onClick={verify}>{checking?'Проверка…':'Проверить подключение'}</button>
      <button className="primary" disabled={checking||adding||!detected?.reachable} onClick={add}>{adding?'Добавление…':'Добавить принтер'}</button>
     </div></div>
    </>}
   </div>}
   {step===2&&<div className="wizardPage"><div className="wizardHeroIcon success"><CheckCircle2/></div><h2>{t('done')}</h2><p>Klipper Farm готов к работе. Принтеры, очередь, камеры и статистика доступны на основной панели.</p><button className="primary wizardNext" onClick={finish}>{t('openFarm')} →</button></div>}
  </main>
 </section></div>;
}

import type { GCodeMetadata, PrinterModel } from '../types';
import type { MoonrakerClient, PrintStartOptions } from './moonraker';
import { hasUsefulGCodeMetadata, inferPrinterPreset, metadataCompatibility } from './gcodeCompatibility';
import { analyzeGCodeFile, analyzeGCodeText, analyzeGCodeTextAsync, type GCodeTextAnalysis } from './gcodeAnalysis';
import { printableArea } from './printerProfile';
import { modelDependentOperationsBlocked } from './modelSafety';

export const GCODE_VALIDATION_ENGINE_VERSION=6;
export type ValidationIssue={level:'error'|'warning'|'info';code:string;message:string};
export type GCodeValidation={ok:boolean;issues:ValidationIssue[];bounds?:{x:number;y:number;z:number};metadata?:GCodeMetadata};

export const printStartOptionsFromValidation=(report:GCodeValidation):PrintStartOptions=>({
  expectsMoonrakerStop:report.issues.some(issue=>issue.code==='forgex_moonraker_stop'),
  estimatedDuration:report.metadata?.estimated_time,
});

const displayBound=(value:number)=>Number.isInteger(value)?String(value):value.toFixed(1);

export function validateGCodeAnalysis(
  printer:PrinterModel,
  filename:string,
  analysis:GCodeTextAnalysis,
  moonrakerMetadata?:GCodeMetadata,
  contentAvailable=true,
):GCodeValidation{
  const issues:ValidationIssue[]=[];
  const profile={bedX:220,bedY:220,maxZ:250,nozzle:.4,materials:['PLA','PETG'],...printer.profile};
  const area=printableArea(profile);
  const coordinateTolerance=profile.preset==='flashforge-ad5m'?1e-6:2;
  const bounds={...analysis.bounds,z:Math.max(moonrakerMetadata?.object_height??0,analysis.bounds.z)};
  const derived:GCodeMetadata={
    filename,
    ...(analysis.metadata.estimatedTime?{estimated_time:analysis.metadata.estimatedTime}:{}),
    ...(analysis.metadata.filamentType?{filament_type:analysis.metadata.filamentType}:{}),
    ...(analysis.metadata.nozzleDiameter?{nozzle_diameter:analysis.metadata.nozzleDiameter}:{}),
    ...(analysis.metadata.layerHeight?{layer_height:analysis.metadata.layerHeight}:{}),
    ...(analysis.metadata.slicer?{slicer:analysis.metadata.slicer}:{}),
    ...(analysis.metadata.printerModel?{printer_model:analysis.metadata.printerModel}:{}),
    ...(analysis.bounds.z>0?{object_height:analysis.bounds.z}:{}),
    ...(analysis.maxHotend>0?{first_layer_extr_temp:analysis.maxHotend}:{}),
    ...(analysis.maxBed>0?{first_layer_bed_temp:analysis.maxBed}:{}),
  };
  const metadata:GCodeMetadata={...derived,...(moonrakerMetadata??{}),filename:moonrakerMetadata?.filename||filename};

  if(modelDependentOperationsBlocked(printer))issues.push({level:'error',code:'model_conflict',message:'Признаки модели противоречат друг другу. Выберите и подтвердите модель вручную в настройках принтера.'});

  if(bounds.x>area.bedX+1)issues.push({level:'error',code:'bed_x',message:`Размер X ${bounds.x.toFixed(1)} мм больше стола ${area.bedX} мм`});
  if(bounds.y>area.bedY+1)issues.push({level:'error',code:'bed_y',message:`Размер Y ${bounds.y.toFixed(1)} мм больше стола ${area.bedY} мм`});
  if(bounds.z>profile.maxZ+1)issues.push({level:'error',code:'height',message:`Высота ${bounds.z.toFixed(1)} мм больше лимита ${profile.maxZ} мм`});
  if(analysis.minX<area.xMin-coordinateTolerance||analysis.maxX>area.xMax+coordinateTolerance){
    issues.push({level:'error',code:'x_range',message:`Координаты X ${analysis.minX.toFixed(1)}…${analysis.maxX.toFixed(1)} мм выходят за стол ${displayBound(area.xMin)}…${displayBound(area.xMax)} мм`});
  }
  if(analysis.minY<area.yMin-coordinateTolerance||analysis.maxY>area.yMax+coordinateTolerance){
    issues.push({level:'error',code:'y_range',message:`Координаты Y ${analysis.minY.toFixed(1)}…${analysis.maxY.toFixed(1)} мм выходят за стол ${displayBound(area.yMin)}…${displayBound(area.yMax)} мм`});
  }

  const quick=metadataCompatibility(printer,metadata);
  if(quick.level==='unknown'){
    issues.push({
      level:contentAvailable?'warning':'error',
      code:'metadata_missing',
      message:contentAvailable?'Служебные метаданные не найдены — файл проверен напрямую по командам G-code':'Метаданные и содержимое G-code недоступны',
    });
  }else{
    quick.reasons.forEach((message,index)=>issues.push({
      level:quick.level==='blocked'?'error':quick.level==='warning'?'warning':'info',
      code:`metadata_${index}`,
      message,
    }));
  }
  if(contentAvailable&&!metadata.nozzle_diameter)issues.push({level:'warning',code:'nozzle_unknown',message:'Диаметр сопла не указан в G-code; используется профиль принтера'});
  if(contentAvailable&&!metadata.filament_type)issues.push({level:'warning',code:'material_unknown',message:'Материал не указан в G-code; проверьте установленную катушку'});

  const maxHotend=Math.max(metadata.first_layer_extr_temp??0,analysis.maxHotend);
  const maxBed=Math.max(metadata.first_layer_bed_temp??0,analysis.maxBed);
  const hotendLimit=profile.maxNozzleTemp??300,bedLimit=profile.maxBedTemp??120;
  if(maxHotend>hotendLimit)issues.push({level:'error',code:'hotend_temp',message:`Сопло ${maxHotend}°C выше лимита ${hotendLimit}°C`});
  if(maxBed>bedLimit)issues.push({level:'error',code:'bed_temp',message:`Стол ${maxBed}°C выше лимита ${bedLimit}°C`});

  if(contentAvailable){
    const headerPreset=inferPrinterPreset(analysis.metadata.printerModel??metadata.printer_model??''),target=printer.profile?.preset;
    const crealityFirmware=profile.firmwareFamily==='creality-klipper'||target==='ender3-v3-ke'||target==='creality-k1c-2025'||target==='creality-k1-max';
    if(headerPreset&&target&&target!=='custom'&&headerPreset!==target)issues.push({level:'error',code:'printer_model',message:`Заголовок G-code указывает профиль ${headerPreset}, выбран ${target}`});
    if(analysis.dangerousCommand)issues.push({level:'error',code:'unsafe_command',message:`Опасная команда в файле: ${analysis.dangerousCommand}`});
    if(analysis.hasCrealityMacro&&!crealityFirmware)issues.push({level:'error',code:'firmware_family',message:'Файл содержит макросы Creality CX_, несовместимые с выбранной прошивкой'});
    if(target==='flashforge-ad5m'){
      if(!analysis.hasForgeStart)issues.push({level:'warning',code:'forgex_start_missing',message:'Forge-X: в файле не найден START_PRINT; удалённый запуск пойдёт напрямую через Moonraker без макроса штатного экрана'});
      else if(!analysis.forgeStartHasParameters)issues.push({level:'warning',code:'forgex_start_params',message:'Forge-X: START_PRINT должен содержать EXTRUDER_TEMP и BED_TEMP в одной строке'});
      if(!analysis.hasForgeEnd)issues.push({level:'warning',code:'forgex_end_missing',message:'Forge-X: END_PRINT не найден; проверьте конечный G-code профиля слайсера'});
      if(analysis.hasStopMod)issues.push({level:'info',code:'forgex_moonraker_stop',message:'Файл отключает Moonraker командой STOP_MOD на время печати; удалённое управление временно станет недоступно'});
    }
  }else{
    issues.push({level:'error',code:'unreadable',message:'Полный текст G-code недоступен — безопасный запуск невозможен'});
  }

  if(!hasUsefulGCodeMetadata(metadata)&&contentAvailable&&!issues.some(issue=>issue.code==='metadata_missing')){
    issues.push({level:'warning',code:'metadata_missing',message:'Файл проверен по G-code без служебных метаданных слайсера'});
  }
  if(!issues.length)issues.push({level:'info',code:'ready',message:'Критических проблем не найдено'});
  return{ok:!issues.some(issue=>issue.level==='error'),issues,bounds,metadata};
}

export function validateGCodeContent(
  printer:PrinterModel,
  filename:string,
  text:string,
  moonrakerMetadata?:GCodeMetadata,
):GCodeValidation{
  return validateGCodeAnalysis(printer,filename,analyzeGCodeText(text),moonrakerMetadata,!!text);
}

export async function validateGCode(client:MoonrakerClient,printer:PrinterModel,filename:string,signal?:AbortSignal):Promise<GCodeValidation>{
  if(signal?.aborted){const error=new Error('Проверка G-code отменена');error.name='AbortError';throw error}
  const uploaded=client.uploadedFile(filename);
  const withReadErrors=(report:GCodeValidation,metadata:PromiseSettledResult<unknown>,text?:PromiseSettledResult<unknown>)=>{
    const reason=(value:unknown)=>String(value instanceof Error?value.message:value);
    if(metadata.status==='rejected'&&!/\bHTTP(?: error)?[: ]+(?:404|405)\b/i.test(reason(metadata.reason)))report.issues.push({level:'warning',code:'metadata_read_error',message:`Метаданные G-code недоступны: ${reason(metadata.reason)}`});
    if(text?.status==='rejected'){report.ok=false;report.issues.push({level:'error',code:'gcode_read_error',message:`Не удалось прочитать G-code: ${reason(text.reason)}`})}
    return report;
  };
  if(uploaded){
    const [metadataResult,analysisResult]=await Promise.allSettled([client.metadata(filename),analyzeGCodeFile(uploaded,signal)]);
    const metadata=metadataResult.status==='fulfilled'?metadataResult.value:undefined;
    if(analysisResult.status==='fulfilled')return withReadErrors(validateGCodeAnalysis(printer,filename,analysisResult.value,metadata,true),metadataResult);
  }
  const [metadataResult,textResult]=await Promise.allSettled([client.metadata(filename),client.gcodeText(filename,signal)]);
  const metadata=metadataResult.status==='fulfilled'?metadataResult.value:undefined;
  const text=textResult.status==='fulfilled'?textResult.value:'';
  const analysis=await analyzeGCodeTextAsync(text,signal);
  return withReadErrors(validateGCodeAnalysis(printer,filename,analysis,metadata,!!text),metadataResult,textResult);
}

