    this.gcodeTextCache.delete(filename);
    this.metadataCache.delete(filename);
    const prefix=`${filename}\u0000`;
    for(const key of this.thumbnailCache.keys())if(key.startsWith(prefix))this.thumbnailCache.delete(key);
