  async upload(file:File,onProgress?:(percent:number)=>void,externalSignal?:AbortSignal):Promise<string>{
    if(file.size>100*1024*1024)throw new Error('G-code превышает лимит 100 MiB');
    if(file.size===0)throw new Error('G-code пуст');
    if(this.uploadInFlight)throw new Error('На этот принтер уже загружается G-code');
    if(externalSignal?.aborted)throw new RequestCancelledError('Загрузка отменена');
    const controller=new AbortController();
    const externalAbort=()=>controller.abort(externalSignal?.reason);
    externalSignal?.addEventListener('abort',externalAbort,{once:true});
    this.uploadController=controller;
    const task=this.runFileTransfer(async signal=>{
      const ensureActive=()=>{if(signal.aborted)throw new RequestCancelledError('Загрузка отменена пользователем')};
      ensureActive();
      onProgress?.(1);
      const expectedSha256=await blobSha256(file);
      ensureActive();
      onProgress?.(3);
      const started=await secureInvoke<NativeUploadBegin>('transactional_upload_begin',{
        ...this.uploadTarget(),
        filename:file.name,
        fileSize:file.size,
        expectedSha256,
      });
      this.activeUploadId=started.uploadId;
      if(started.completedPath){
        this.uploadedHashes.set(started.completedPath,expectedSha256);
        this.uploadedFiles.set(started.completedPath,file);
        this.activeUploadId=undefined;
        onProgress?.(100);
        return started.completedPath;
      }
      const chunkSize=Math.max(64*1024,Math.min(512*1024,Math.trunc(started.chunkSize)||512*1024));
      let offset=Math.max(0,Math.min(file.size,Math.trunc(started.receivedSize)||0)),finished=false;
      if(offset>0)onProgress?.(Math.max(3,Math.min(94,Math.round(offset/file.size*91)+3)));
      try{
        while(offset<file.size){
          ensureActive();
          const end=Math.min(file.size,offset+chunkSize);
          const data=Array.from(new Uint8Array(await file.slice(offset,end).arrayBuffer()));
          ensureActive();
          const received=await secureInvoke<number>('transactional_upload_chunk',{uploadId:started.uploadId,offset,data});
          if(received!==end)throw new Error('Staging-журнал подтвердил неверный размер блока G-code');
          offset=end;
          onProgress?.(Math.max(3,Math.min(94,Math.round(offset/file.size*91)+3)));
        }
        ensureActive();
        onProgress?.(95);
        const result=await secureInvoke<NativeUploadFinish>('transactional_upload_finish',{uploadId:started.uploadId});
        finished=true;
        this.uploadedHashes.set(result.path,result.sha256);
        this.uploadedFiles.set(result.path,file);
        while(this.uploadedHashes.size>32)this.uploadedHashes.delete(this.uploadedHashes.keys().next().value as string);
        while(this.uploadedFiles.size>8)this.uploadedFiles.delete(this.uploadedFiles.keys().next().value as string);
        this.invalidateFileCaches(result.path);
        onProgress?.(100);
        return result.path;
      }finally{
        if(this.activeUploadId===started.uploadId)this.activeUploadId=undefined;
        // Transport errors preserve the staged file for resume. Only an
        // explicit user cancellation destroys the resumable transaction.
        if(!finished&&signal.aborted)await secureInvoke<boolean>('transactional_upload_abort',{uploadId:started.uploadId}).catch(error=>{diagnosticWarning('moonraker.upload.abort',error,{printerId:this.config.id,operation:'upload.abort'});return false});
      }
    },controller.signal,'upload.gcode');
    this.uploadInFlight=task;
    try{return await task}
    finally{
      externalSignal?.removeEventListener('abort',externalAbort);
      if(this.uploadInFlight===task)this.uploadInFlight=undefined;
      if(this.uploadController===controller)this.uploadController=undefined;
    }
  }
  cancelUpload(){if(!this.uploadController)return false;this.uploadController.abort('Загрузка отменена пользователем');return true}
  uploadActive(){return!!this.uploadController}
  uploadedSha256(filename:string){return this.uploadedHashes.get(filename)}
  uploadedFile(filename:string){return this.uploadedFiles.get(filename)}
}

import type { GCodeFileEntry } from '../types';

type FileReader={list:()=>Promise<unknown>;directory:(path:string)=>Promise<unknown>;signal?:AbortSignal};
const record=(value:unknown):Record<string,unknown>|undefined=>value!==null&&typeof value==='object'&&!Array.isArray(value)?value as Record<string,unknown>:undefined;
const unavailable=(error:unknown)=>{
  const message=String(error instanceof Error?error.message:record(error)?.message??error);
  const status=message.match(/\bHTTP(?: error)?[: ]+(\d{3})\b/i);
  if(status)return status[1]==='404'||status[1]==='405';
  if(/\b(?:401|403|5\d\d)\b|unauthori[sz]ed|forbidden|api[ _-]?key|time[ -]?out|timed out|abort|cancel/i.test(message))return false;
  const code=record(error)?.code;
  if(code!==undefined)return code===-32601;
  return /\b(?:method not found|unknown method)\b|(?:^|\D)-32601\b/i.test(message);
};
const payload=(value:unknown,depth=0):unknown=>{
  if(depth>8)throw new Error('Moonraker вернул некорректную вложенность ответа файлов');
  const object=record(value);
  if(object&&Object.hasOwn(object,'error')&&object.error!==null){
    throw Object.assign(new Error(`Moonraker: ${JSON.stringify(object.error)}`),{code:record(object.error)?.code});
  }
  if(object&&(object.partial===true||object.truncated===true||object.complete===false))throw new Error('Moonraker вернул неполный список файлов');
  return object&&Object.hasOwn(object,'result')?payload(object.result,depth+1):value;
};
const safePath=(value:unknown):value is string=>typeof value==='string'&&value.length>0&&value.length<=2048&&!/[\\\x00-\x1f]/.test(value)&&!value.startsWith('/')&&!value.split('/').some(part=>!part||part==='.'||part==='..');
const entry=(value:unknown,path:string):GCodeFileEntry=>{
  const item=record(value);
  if(!item||!safePath(path)||(item.size!==undefined&&(!Number.isSafeInteger(item.size)||Number(item.size)<0))
    ||(item.modified!==undefined&&(typeof item.modified!=='number'||!Number.isFinite(item.modified))))throw new Error('Moonraker вернул некорректную запись файла');
  return{path,...(item.size!==undefined?{size:Number(item.size)}:{}),...(item.modified!==undefined?{modified:Number(item.modified)}:{})};
};
const addEntry=(files:Map<string,GCodeFileEntry>,item:GCodeFileEntry)=>{
  const previous=files.get(item.path);
  if(previous&&(previous.size!==item.size||previous.modified!==item.modified))throw new Error('Moonraker вернул противоречивые записи файла');
  files.set(item.path,item);
  if(files.size>20_000)throw new Error('Каталог принтера превышает лимит 20 000 файлов');
};

/** Both RPC result arrays and HTTP envelopes occur on supported firmware.
 * Directory fallback stays in gcodes, walks subfolders, and fails atomically:
 * a missing child must never replace the saved index with a partial list.
 */
export async function readGCodeFileEntries(reader:FileReader):Promise<GCodeFileEntry[]>{
  const checkCancelled=()=>{if(reader.signal?.aborted)throw new DOMException('Чтение списка файлов отменено','AbortError')};
  checkCancelled();
  try{
    const result=payload(await reader.list());
    checkCancelled();
    if(!Array.isArray(result))throw new Error('Moonraker вернул некорректный список файлов');
    const files=new Map<string,GCodeFileEntry>();
    for(const item of result)addEntry(files,entry(item,record(item)?.path as string));
    return [...files.values()];
  }catch(error){if(!unavailable(error))throw error}
  const pending=['gcodes'],seen=new Set(pending),files=new Map<string,GCodeFileEntry>();
  while(pending.length){
    checkCancelled();
    const path=pending.shift()!;
    let value:unknown;
    try{value=payload(await reader.directory(path))}catch(error){
      if(path==='gcodes'&&unavailable(error))throw new Error('Moonraker не предоставляет список файлов: методы списка и каталога недоступны. Проверьте порт Moonraker и компонент file_manager.');
      throw error;
    }
    checkCancelled();
    const directory=record(value);
    if(!directory||!Array.isArray(directory.files)||!Array.isArray(directory.dirs))throw new Error('Moonraker вернул некорректный каталог файлов');
    const prefix=path==='gcodes'?'':path.slice('gcodes/'.length)+'/';
    for(const item of directory.files){
      const name=record(item)?.filename;
      if(!safePath(name)||name.includes('/'))throw new Error('Moonraker вернул некорректное имя файла каталога');
      const file=entry(item,prefix+name);
      if(/\.(?:gcode|gco|g|gx|g3d|ufp)$/i.test(name))addEntry(files,file);
    }
    for(const item of directory.dirs){
      const name=record(item)?.dirname;
      if(!safePath(name)||name.includes('/'))throw new Error('Moonraker вернул некорректное имя папки каталога');
      const child=path+'/'+name;
      if(seen.has(child))continue;
      if(seen.size>=256||child.split('/').length>17)throw new Error('Каталог принтера содержит слишком много вложенных папок');
      seen.add(child);pending.push(child);
    }
  }
  return [...files.values()];
}

