.kfPrinterGrid{grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.kfTelemetryCard{min-height:405px;padding:13px;border-color:#1b4168;background:linear-gradient(145deg,#06101d,#030913);box-shadow:inset 0 1px #68baff12,0 16px 34px #0005}.kfTelemetryHead{gap:8px;padding-right:31px}.kfTelemetryHead h2{font-size:17px}.kfTelemetryLive{max-width:112px}.kfTelemetryBody{grid-template-columns:minmax(135px,.82fr) minmax(190px,1.18fr);gap:10px;margin-top:9px}.kfTelemetryMachine{height:205px;isolation:isolate;overflow:visible;background:radial-gradient(ellipse at 50% 72%,#0878dc55 0,#07386c24 37%,transparent 68%)}.kfTelemetryMachine:before{content:"";position:absolute;z-index:-2;left:5%;right:5%;bottom:7%;height:33%;border-radius:50%;background:radial-gradient(ellipse,#0a79d05c 0,#063a7235 38%,transparent 72%);filter:blur(8px);transform:perspective(180px) rotateX(64deg)}.kfTelemetryMachine:after{content:"";position:absolute;z-index:-1;left:17%;right:17%;bottom:8%;height:8%;border-radius:50%;background:#000a;filter:blur(7px)}.kfTelemetryMachine img{height:202px;width:100%;object-fit:contain;filter:drop-shadow(0 14px 10px #000a) drop-shadow(0 0 10px #168cff33);transform:translateY(-2px);transition:transform .35s ease,filter .35s ease}.kfTelemetryCard:hover .kfTelemetryMachine img{transform:translateY(-6px) scale(1.025);filter:drop-shadow(0 18px 12px #000b) drop-shadow(0 0 15px #168cff55)}.kfTelemetryMachine>strong{font-size:24px;z-index:2;text-shadow:0 2px 12px #020812}.kfTelemetryMachine>span{z-index:2;text-shadow:0 2px 8px #020812}.kfTelemetryData{gap:6px}.kfTelemetryTemp{grid-template-columns:82px 1fr;gap:5px;padding-bottom:5px}.kfTelemetryTemp b{font-size:14px}.kfTelemetryTemp svg{height:42px}.kfTelemetryStats{gap:4px}.kfTelemetryStats>div{grid-template-columns:15px 1fr;gap:0 4px;padding:6px 5px}.kfTelemetryStats svg{width:12px}.kfTelemetryStats b{font-size:10px}.kfTelemetryJob{margin-top:8px}.kfTelemetryFoot{grid-template-columns:54px 59px 58px 1fr;gap:5px;margin-top:9px}.kfTelemetryActions{gap:4px}.kfTelemetryActions button{padding:5px 6px}.kfTelemetryProgress{margin-top:5px}
