.kfTelemetryMachine{background:radial-gradient(ellipse at 50% 76%,#00bfff38 0,#063d7a24 36%,transparent 68%);clip-path:inset(0 round 8px)}.kfTelemetryMachine img{height:215px;filter:drop-shadow(0 0 5px #00c8ff88) drop-shadow(0 12px 12px #000a);mix-blend-mode:screen}.kfTelemetryMachine:before{background:radial-gradient(ellipse,#00c8ff42 0,#0867a82c 38%,transparent 72%);animation:kfHologramPulse 3.2s ease-in-out infinite}.kfHologramScan{position:absolute;z-index:3;left:8%;right:8%;top:8%;height:2px;background:linear-gradient(90deg,transparent,#45e8ff,#fff,#45e8ff,transparent);box-shadow:0 0 9px 2px #00c8ff99;opacity:0;pointer-events:none;animation:kfHologramScan 3.8s ease-in-out infinite}.state-printing .kfHologramScan{animation-duration:2.2s}.state-printing .kfTelemetryMachine img{filter:drop-shadow(0 0 6px #2bf6a9aa) drop-shadow(0 12px 12px #000a)}.state-error .kfTelemetryMachine img{filter:hue-rotate(135deg) drop-shadow(0 0 7px #ff3b69bb) drop-shadow(0 12px 12px #000a)}@keyframes kfHologramScan{0%,18%{top:8%;opacity:0}25%{opacity:.85}72%{opacity:.75}80%,100%{top:88%;opacity:0}}@keyframes kfHologramPulse{50%{opacity:.62;transform:perspective(180px) rotateX(64deg) scale(1.08)}}@media(prefers-reduced-motion:reduce){.kfHologramScan,.kfTelemetryMachine:before{animation:none!important}.kfHologramScan{display:none}}
