/* v1.13: farm command dashboard */
.kfCyberEyebrow.farmOnline{color:#35e98d;text-shadow:0 0 12px #35e98d55}
.fleetCommand{--fleet-line:#15527a;--fleet-muted:#7089a3;--fleet-panel:#030a13;margin-top:12px;display:grid;gap:10px;color:#eaf4ff;font-family:"Segoe UI Variable Display","Segoe UI",sans-serif}
.fleetCommandTop{display:grid;grid-template-columns:260px minmax(450px,1fr) 330px;grid-template-rows:minmax(480px,calc(100vh - 360px));gap:10px;min-width:0}
.fleetCommandBottom{min-height:350px;display:grid;grid-template-columns:minmax(250px,.72fr) minmax(0,2.28fr);gap:10px;min-width:0}
.fleetCommandPanel{position:relative;min-width:0;min-height:0;overflow:hidden;border:1px solid var(--fleet-line);background:linear-gradient(145deg,#04101bf7,#02070df7);box-shadow:inset 0 0 36px #07264a22,0 12px 28px #0004}
.fleetCommandPanel:before,.fleetCommandPanel:after{content:"";position:absolute;z-index:4;width:20px;height:20px;pointer-events:none}
.fleetCommandPanel:before{left:-1px;top:-1px;border-left:2px solid #25cfff;border-top:2px solid #8251ff}
.fleetCommandPanel:after{right:-1px;bottom:-1px;border-right:2px solid #25cfff;border-bottom:2px solid #8251ff}
.fleetCommandPanel>header{height:43px;display:flex;align-items:center;gap:8px;padding:0 12px;border-bottom:1px solid #143957;background:#06111ccc;font-size:10px;letter-spacing:.05em}
.fleetCommandPanel>header>svg{width:15px;color:#885dff;filter:drop-shadow(0 0 5px #754aff88)}
.fleetCommandPanel>header>b{font-size:11px;color:#edf5ff}
.fleetCommandPanel>header>span{margin-left:auto;color:#5f7b95;font-size:8px;letter-spacing:.12em}
.fleetCommandPanel>header>button{margin-left:auto;height:100%;border:0;background:transparent;color:#63a9d1;display:flex;align-items:center;gap:2px;font-size:8px;letter-spacing:.08em}
.fleetCommandPanel>header>button:hover{color:#37dfff}
.fleetCommandPanel>header>button svg{width:13px}

.fleetRoster{display:flex;flex-direction:column}
.fleetRosterList{min-height:0;overflow-y:auto;padding:10px;display:grid;align-content:start;gap:8px;scrollbar-width:thin;scrollbar-color:#1b4665 transparent}
.fleetRosterList>button{position:relative;width:100%;min-height:112px;display:grid;grid-template-columns:70px minmax(0,1fr) 34px;gap:8px;align-items:center;padding:8px;border:1px solid #163956;background:#06111c;color:#d7e5f4;text-align:left;clip-path:polygon(0 0,calc(100% - 9px) 0,100% 9px,100% 100%,9px 100%,0 calc(100% - 9px))}
.fleetRosterList>button:hover{border-color:#29cbf5;background:#071a2a}
.fleetRosterList>button.selected{border-color:#724cff;background:radial-gradient(circle at 85% 20%,#3a196b66,transparent 55%),#081321;box-shadow:inset 0 0 22px #713eff22,0 0 13px #5b3cff22}
.fleetRosterList>button>img{width:70px;height:84px;object-fit:contain;filter:drop-shadow(0 10px 9px #0009)}
.fleetRosterList>button>span{min-width:0;display:grid;gap:5px}
.fleetRosterList>button strong,.fleetRosterList>button em,.fleetRosterList>button small{display:block;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.fleetRosterList>button strong{font-size:11px}.fleetRosterList>button strong i{display:inline-block;width:7px;height:7px;margin-right:6px;border-radius:50%;background:#38e68a;box-shadow:0 0 8px #38e68a}
.fleetRosterList>button em{font-style:normal;color:#43e58e;font-size:10px}
.fleetRosterList>button small{color:#57738c;font-size:8px}
.fleetRosterList>button>b{align-self:center;color:#b6c5d6;font-size:10px}
.fleetRosterList>button.state-printing strong i{background:#8a58ff;box-shadow:0 0 9px #8a58ff}.fleetRosterList>button.state-printing em{color:#a47bff}
.fleetRosterList>button.state-paused strong i{background:#ffad3d;box-shadow:0 0 9px #ffad3d}.fleetRosterList>button.state-paused em{color:#ffad3d}
.fleetRosterList>button.state-offline strong i,.fleetRosterList>button.state-error strong i{background:#ff4f62;box-shadow:0 0 9px #ff4f62}.fleetRosterList>button.state-offline em,.fleetRosterList>button.state-error em{color:#ff6474}
.fleetMiniBar{width:100%;height:4px!important;background:#10283c;overflow:hidden}.fleetMiniBar>i{display:block;height:100%;background:linear-gradient(90deg,#7e48ff,#357cff);box-shadow:0 0 8px #6e4cff}
.fleetRosterEmpty{height:260px;display:grid;place-items:center;align-content:center;gap:8px;color:#66839c;text-align:center}.fleetRosterEmpty>svg{width:36px;color:#35ccff}.fleetRosterEmpty>b{font-size:11px}.fleetRosterEmpty>button{border:1px solid #185678;background:#072037;color:#49ddff;padding:8px 11px}

.fleetActiveHero{display:flex;flex-direction:column;background:radial-gradient(circle at 48% 45%,#11206999 0,#050b18 42%,#02070d 73%)}
.fleetHeroCanvas{position:relative;min-height:0;flex:1;overflow:hidden}
.fleetHeroGrid{position:absolute;inset:0;background-image:linear-gradient(#34649a13 1px,transparent 1px),linear-gradient(90deg,#34649a13 1px,transparent 1px);background-size:30px 30px;mask-image:linear-gradient(to bottom,#000,transparent 115%)}
.fleetHeroCanvas>img{position:absolute;z-index:2;left:3%;bottom:1%;width:58%;height:82%;object-fit:contain;filter:drop-shadow(0 24px 22px #000c) drop-shadow(0 0 12px #2c78df44)}
