/* v1.14: neon circuit HUD skin */
:root,:root[data-theme="dark"],:root[data-theme="light"]{
  --hud-bg:#01040a;
  --hud-deep:#02060d;
  --hud-panel:#030a13f5;
  --hud-panel-2:#06101bf2;
  --hud-line:#11516f;
  --hud-line-soft:#12344b;
  --hud-cyan:#18d9ff;
  --hud-blue:#2878ff;
  --hud-violet:#7547ff;
  --hud-magenta:#f02cff;
  --hud-green:#35e98b;
  --hud-amber:#ffae3d;
  --hud-red:#ff4d68;
  --hud-text:#eef7ff;
  --hud-muted:#748aa1;
  color-scheme:dark;
  background:var(--hud-bg);
  color:var(--hud-text);
}
:root[data-theme="light"]{--hud-panel:#06121df7;--hud-panel-2:#091825f5;--hud-muted:#8ca3b9}
:root body,:root[data-theme="light"] body{background:var(--hud-bg);color:var(--hud-text)}
:root ::selection{background:#7a45ff80;color:#fff}

.kfShell{
  grid-template-columns:218px minmax(0,1fr);
  background:
    radial-gradient(circle at 74% 4%,#39107835 0,transparent 27%),
    radial-gradient(circle at 31% 42%,#063d6838 0,transparent 34%),
    linear-gradient(145deg,#01040a,#020711 56%,#02040a);
}
.kfAmbient{
  opacity:1!important;
  mask-image:none;
  background-image:
    linear-gradient(90deg,transparent 0 12%,#19d8ff0d 12% 12.08%,transparent 12.08% 43%,#7a4cff0e 43% 43.08%,transparent 43.08%),
    linear-gradient(0deg,transparent 0 19%,#19d8ff0c 19% 19.1%,transparent 19.1% 67%,#f02cff0b 67% 67.1%,transparent 67.1%),
    linear-gradient(#23618f0b 1px,transparent 1px),
    linear-gradient(90deg,#23618f0b 1px,transparent 1px);
  background-size:100% 100%,100% 100%,34px 34px,34px 34px;
}
.kfAmbient:before{content:"";position:absolute;inset:0;opacity:.55;background:
  linear-gradient(90deg,transparent 7%,#0ecfff2a 7% 7.08%,transparent 7.08% 100%),
  linear-gradient(0deg,transparent 28%,#0ecfff20 28% 28.08%,transparent 28.08% 100%),
  radial-gradient(circle at 7% 28%,#26e6ff 0 2px,transparent 3px),
  linear-gradient(90deg,transparent 64%,#ed32ff1c 64% 64.07%,transparent 64.07% 100%),
  linear-gradient(0deg,transparent 77%,#ed32ff1c 77% 77.08%,transparent 77.08% 100%),
  radial-gradient(circle at 64% 77%,#ed32ff 0 2px,transparent 3px)}
.kfAmbient:after{inset:0;background:radial-gradient(ellipse at center,transparent 35%,#01040a77 78%,#01040ae8 100%)}
.kfAmbientGlow{opacity:.09;filter:blur(100px)}.kfAmbientGlow.one{background:#134cff}.kfAmbientGlow.two{background:#d523ff}

.kfSidebar,.kfDetailSidebar{
  background:
    linear-gradient(90deg,transparent 82%,#18d9ff0b 82% 82.6%,transparent 82.6%),
    linear-gradient(0deg,transparent 36%,#7048ff0d 36% 36.5%,transparent 36.5%),
    linear-gradient(180deg,#02060dfb,#01050bfb)!important;
  border-color:#105171!important;
  box-shadow:inset -10px 0 36px #05274322,18px 0 48px #0009!important;
}
.kfSidebar{padding:14px 10px 12px}
.kfSidebar:before,.kfDetailSidebar:before{content:"";position:absolute;inset:74px 0 0;pointer-events:none;opacity:.42;background:
  linear-gradient(90deg,transparent 17px,#13d5ff30 18px,transparent 19px) 0 82%/100% 1px no-repeat,
  linear-gradient(0deg,transparent 17px,#13d5ff28 18px,transparent 19px) 18px 0/1px 100% no-repeat,
  radial-gradient(circle at 18px 82%,#22ddff 0 2px,transparent 3px),
  repeating-linear-gradient(0deg,transparent 0 51px,#17415a22 52px,#17415a22 53px)}
.kfSidebar:after,.kfDetailSidebar:after{content:"";position:absolute;z-index:3;right:-1px;top:0;bottom:0;width:1px;background:linear-gradient(transparent,#20dcff 18%,#6d48ff 48%,#ef2dff 72%,transparent);box-shadow:0 0 13px #1edcff66;pointer-events:none}
