/* v1.14.4 — rebuilt Moonraker file deck: roomy cards, live storage telemetry and safe responsive flow. */
.printerFilesBackdrop{
  padding:14px;
  overflow:hidden;
  background:radial-gradient(circle at 50% 0,#07386b57,transparent 38%),#01040be8;
}
.printerFilesPanel{
  position:relative;
  isolation:isolate;
  width:min(1240px,calc(100vw - 28px))!important;
  height:min(900px,calc(100vh - 28px));
  min-height:0!important;
  max-height:calc(100vh - 28px)!important;
  padding:0!important;
  overflow:hidden!important;
  display:flex;
  flex-direction:column;
  border:1px solid #1d7593!important;
  border-radius:0!important;
  background:
    radial-gradient(circle at 84% -14%,#9327dc2b,transparent 36%),
    radial-gradient(circle at 12% 22%,#0c91be1b,transparent 30%),
    linear-gradient(155deg,#071520 0,#020912 58%,#040714 100%)!important;
  box-shadow:0 30px 90px #000e,0 0 32px #1ddfff22,0 0 40px #c22bff14!important;
  color:#eaf8ff!important;
}
.printerFilesPanel:before,.printerFilesPanel:after{
  content:"";
  position:absolute;
  z-index:3;
  width:112px;
  height:2px;
  pointer-events:none;
}
.printerFilesPanel:before{left:0;top:0;background:#2ce6ff;box-shadow:0 0 14px #2ce6ff}
.printerFilesPanel:after{right:0;bottom:0;background:#dc35ff;box-shadow:0 0 14px #dc35ff}
.printerFilesPanel> *{position:relative;z-index:1}
.printerFilesPanel>.printerFilesHead{
  position:relative!important;
  top:auto!important;
  flex:0 0 auto;
  min-height:76px;
  margin:0!important;
  padding:12px 15px!important;
  align-items:center;
  border-bottom:1px solid #185169!important;
  background:linear-gradient(90deg,#071925f5,#070b1df7 70%,#120820f4)!important;
  box-shadow:0 8px 22px #0005;
}
.printerFilesHead:after{content:none!important}
.printerFilesHead:before{
  content:"";
  position:absolute;
  left:0;
  bottom:-1px;
  width:38%;
  height:1px;
  background:linear-gradient(90deg,#2ce6ff,transparent);
  box-shadow:0 0 9px #2ce6ff;
}
.printerFilesTitle{min-width:0;display:flex;align-items:center;gap:12px}
.printerFilesTitle>i{
  width:46px;
  height:46px;
  flex:none;
  display:grid;
  place-items:center;
  border:1px solid #2cdcf6;
  background:linear-gradient(145deg,#0a2d40,#071229);
  color:#52e9ff;
  box-shadow:inset 0 0 18px #22dcff24,0 0 15px #22dcff1c;
  clip-path:polygon(0 0,calc(100% - 7px) 0,100% 7px,100% 100%,7px 100%,0 calc(100% - 7px));
}
.printerFilesTitle>i svg{width:23px;filter:drop-shadow(0 0 6px #37ddff99)}
.printerFilesTitle>span,.printerFilesTitle small,.printerFilesTitle h2,.printerFilesTitle p{display:block;min-width:0}
.printerFilesTitle small{margin:0 0 3px;color:#55dff8;font-size:7px;font-weight:800;letter-spacing:.19em}
.printerFilesTitle h2{margin:0!important;color:#f2f9ff!important;font-size:20px!important;line-height:1.1;letter-spacing:.01em!important;text-shadow:0 0 16px #25dfff2d}
.printerFilesTitle p{margin:4px 0 0!important;overflow:hidden;color:#718ea1!important;font-size:9px!important;text-overflow:ellipsis;white-space:nowrap}
.printerFilesHeadActions{display:flex;align-items:center;gap:7px;flex:none}
.printerFilesHeadActions>button{
  height:38px;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:7px;
  padding:0 11px;
  border:1px solid #20556c;
  border-radius:0;
  background:#06131e;
  color:#a7c4d3;
  font-size:9px;
  clip-path:polygon(0 0,calc(100% - 5px) 0,100% 5px,100% 100%,5px 100%,0 calc(100% - 5px));
}
.printerFilesHeadActions>button:hover:not(:disabled){border-color:#3de7ff;color:#fff;box-shadow:inset 0 0 15px #20dfff1b,0 0 12px #20dfff1c}
.printerFilesHeadActions>button:disabled{opacity:.55}
.printerFilesHeadActions>button svg{width:15px}
.printerFilesHeadActions>button.round{width:38px;padding:0}
.printerFilesConnection{
  height:30px;
  display:flex;
  align-items:center;
  gap:6px;
  padding:0 9px;
  border:1px solid #246a54;
  background:#08251c;
  color:#62e7a8;
  font-size:8px;
  font-weight:750;
  letter-spacing:.04em;
  white-space:nowrap;
}
.printerFilesConnection>i{width:6px;height:6px;border-radius:50%;background:#45e99b;box-shadow:0 0 9px #45e99b;animation:printerFilesPulse 1.8s ease-in-out infinite}
.printerFilesConnection>svg{width:13px}
.printerFilesConnection.state-printing,.printerFilesConnection.state-paused{border-color:#357194;background:#092131;color:#55dfff}
.printerFilesConnection.state-error{border-color:#8a3a4d;background:#2c1119;color:#ff8395}
.printerFilesConnection.state-offline{border-color:#4d5964;background:#141a20;color:#8798a4}
.printerFilesConnection.state-error>i{background:#ff5c75;box-shadow:0 0 9px #ff5c75}
.printerFilesConnection.state-offline>i{background:#647784;box-shadow:none;animation:none}

.printerFilesOverview{
  flex:0 0 auto;
  min-height:86px;
  display:grid;
  grid-template-columns:minmax(218px,.75fr) minmax(0,2.45fr);
  gap:8px;
  margin:10px 12px 8px;
}
.printerFilesNode,.printerFilesStats>div{
  position:relative;
  overflow:hidden;
  border:1px solid #17485f;
  background:linear-gradient(145deg,#071824,#040d17);
  clip-path:polygon(0 0,calc(100% - 7px) 0,100% 7px,100% 100%,7px 100%,0 calc(100% - 7px));
}
.printerFilesNode:after,.printerFilesStats>div:after{
  content:"";
  position:absolute;
  right:-18px;
  top:-24px;
  width:70px;
  height:70px;
  border:1px solid #2ce5ff12;
  transform:rotate(45deg);
}
.printerFilesNode{display:flex;align-items:center;gap:11px;padding:11px 12px;border-color:#1a637b;background:radial-gradient(circle at 12% 50%,#0c9fb72c,transparent 44%),#04131d}
.printerFilesNode>i{width:42px;height:42px;display:grid;place-items:center;flex:none;border:1px solid #23718a;background:#082635;color:#49e4ff;box-shadow:inset 0 0 16px #28deff21}
.printerFilesNode>i svg{width:21px}
.printerFilesNode span,.printerFilesNode small,.printerFilesNode strong,.printerFilesNode em{display:block;min-width:0}
.printerFilesNode small{color:#4bbdd2;font-size:7px;font-weight:800;letter-spacing:.14em}
.printerFilesNode strong{margin-top:3px;color:#ddf8ff;font-size:13px}
.printerFilesNode em{max-width:170px;margin-top:4px;overflow:hidden;color:#628497;font-size:8px;font-style:normal;text-overflow:ellipsis;white-space:nowrap}
.printerFilesOverview.state-error .printerFilesNode{border-color:#7f3549;background:radial-gradient(circle at 12% 50%,#da345625,transparent 44%),#160b12}
.printerFilesOverview.state-error .printerFilesNode>i{border-color:#82384b;background:#2b1019;color:#ff748b}
.printerFilesOverview.state-offline .printerFilesNode{filter:saturate(.35)}
.printerFilesConnection.state-connecting{border-color:#286b93;background:#091d2b;color:#6fcaff}
.printerFilesConnection.state-connecting>i{background:#55b8ff;box-shadow:0 0 9px #55b8ff;animation:kfConnectionPulse 1.25s ease-in-out infinite}
.printerFilesOverview.state-connecting .printerFilesNode{border-color:#286b93;background:radial-gradient(circle at 12% 50%,#2b9bd522,transparent 44%),#07141e}

/* Four-state connection telemetry: connecting and reachable/degraded are not offline. */
.kfTelemetryLive.pending i{background:#55b8ff;box-shadow:0 0 12px #55b8ff;animation:kfConnectionPulse 1.25s ease-in-out infinite}
.kfTelemetryCard.connection-connecting{border-color:#286aa0;box-shadow:inset 0 1px #66c9ff20,0 16px 34px #0005}
.kfTelemetryCard.connection-degraded{border-color:#8a662d;box-shadow:inset 0 1px #ffc15a24,0 16px 34px #0005}
.kfTelemetryCard.connection-degraded .kfTelemetryLive.yes i{background:#ffb54b;box-shadow:0 0 12px #ffb54b}
.kfTelemetryCard.connection-degraded .kfTelemetryLive b{color:#ffc66b}
.kfTelemetryCard.connection-degraded.state-error .kfTelemetryMachine img{filter:sepia(.22) drop-shadow(0 0 7px #ffb94d88) drop-shadow(0 12px 12px #000a)}
@keyframes kfConnectionPulse{50%{opacity:.38;transform:scale(.72)}}
@media(prefers-reduced-motion:reduce){.kfTelemetryLive.pending i{animation:none}}
.gcodeThumbnailAsset{width:100%;height:100%;display:grid;place-items:center;overflow:hidden;font-style:normal}
.gcodeThumbnailAsset>img{width:100%;height:100%;display:block;object-fit:contain}
.gcodeThumbnailAsset>svg{width:42%;height:42%}
.printerFileThumb>.gcodeThumbnailAsset{height:calc(100% - 18px);align-self:start}
.printerFileThumb>.gcodeThumbnailAsset>img{width:100%;height:100%;object-fit:contain;filter:drop-shadow(0 7px 8px #0008)}
.printerFileThumb>.gcodeThumbnailAsset>svg{width:30px;height:30px;color:var(--file-accent);filter:drop-shadow(0 0 8px color-mix(in srgb,var(--file-accent) 65%,transparent))}
.discoveryDeviceState.error{border-color:#8a642f!important;background:#2a1c0c!important;color:#ffc261!important}
.discoveryResults article small.errorText{color:#dcae65!important}
.printerFilesStats{min-width:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px}
.printerFilesStats>div{min-width:0;display:grid;grid-template-columns:34px minmax(0,1fr);align-items:center;gap:8px;padding:9px 10px}
.printerFilesStats>div:before{content:"";position:absolute;left:0;top:0;width:28px;height:1px;background:#35ddff;box-shadow:0 0 8px #35ddff}
