/* WebView2 stability: the file window used to combine backdrop blur,
   deferred paint surfaces and animated GPU filters. On some integrated GPUs
   that produced short-lived green tiles while opening or scrolling. */
.printerFilesBackdrop{
  backdrop-filter:none!important;
  -webkit-backdrop-filter:none!important;
  background:radial-gradient(circle at 50% 0,#07386b57,transparent 38%),#01050df7!important;
}
.printerFilesPanel{
  transform:none!important;
  backface-visibility:visible!important;
  will-change:auto!important;
}
.printerFilesPanel .printerFileCard,
.printerFilesPanel .localFileCard{
  content-visibility:visible!important;
  contain:none!important;
  contain-intrinsic-size:none!important;
}
.printerFilesPanel img,
.printerFilesPanel svg{
  filter:none!important;
  mix-blend-mode:normal!important;
}
.printerFilesPanel .printerFilesConnection>i,
.printerFilesPanel .printerFilesDrop.active:before{
  animation:none!important;
  transform:none!important;
}
.printerFileDialogBackdrop{
  backdrop-filter:none!important;
  -webkit-backdrop-filter:none!important;
  background:#01050df5!important;
}
.printerFileDialog{clip-path:none!important}
:root[data-theme="light"] .printerFilesBackdrop{background:#dce7f2f7!important}

