/* ==========================================================================
   KLIPPER FARM — PRODUCTIVITY UI 2026
   Shared light/dark design system. Solid surfaces deliberately avoid
   WebView2 blur/filter artifacts on integrated graphics.
   ========================================================================== */
:root[data-theme="light"]{
  --ui-bg:#f3f5f8;
  --ui-surface:#ffffff;
  --ui-surface-2:#f7f9fc;
  --ui-surface-3:#eef2f7;
  --ui-border:#dde3ec;
  --ui-border-strong:#cbd4e1;
  --ui-text:#172033;
  --ui-muted:#667085;
  --ui-subtle:#8b95a5;
  --ui-accent:#2563eb;
  --ui-accent-hover:#1d4ed8;
  --ui-accent-soft:#eaf1ff;
  --ui-success:#16a34a;
  --ui-success-soft:#eaf8ef;
  --ui-warning:#d97706;
  --ui-warning-soft:#fff4e5;
  --ui-danger:#dc2626;
  --ui-danger-soft:#fff0f0;
  --ui-shadow:0 8px 28px rgba(24,36,56,.08);
  --ui-shadow-soft:0 2px 10px rgba(24,36,56,.055);
  --ui-overlay:rgba(34,43,58,.48);
  background:var(--ui-bg);
  color:var(--ui-text);
}
:root[data-theme="dark"]{
  --ui-bg:#101216;
  --ui-surface:#181b21;
  --ui-surface-2:#20242c;
  --ui-surface-3:#272c35;
  --ui-border:#2d333d;
  --ui-border-strong:#3a424f;
  --ui-text:#f3f5f8;
  --ui-muted:#a1a9b6;
  --ui-subtle:#778190;
  --ui-accent:#6f8cff;
  --ui-accent-hover:#89a0ff;
  --ui-accent-soft:#222c4b;
  --ui-success:#4ac47a;
  --ui-success-soft:#183424;
  --ui-warning:#f0a54a;
  --ui-warning-soft:#3a2b19;
  --ui-danger:#f06a6a;
  --ui-danger-soft:#3c2022;
  --ui-shadow:0 12px 34px rgba(0,0,0,.26);
  --ui-shadow-soft:0 3px 12px rgba(0,0,0,.2);
  --ui-overlay:rgba(3,5,8,.72);
  background:var(--ui-bg);
  color:var(--ui-text);
}
:root[data-theme] body,
:root[data-theme] #root{min-height:100%;background:var(--ui-bg)!important;color:var(--ui-text)!important}
:root[data-theme] ::selection{background:var(--ui-accent-soft);color:var(--ui-text)}
:root[data-theme] *{scrollbar-color:var(--ui-border-strong) transparent}
:root[data-theme] :where(.kfShell,.panel,.kfWorkspace,.kfDetailShell,.printerFilesPanel,.discoveryPanel){color:var(--ui-text)}
:root[data-theme] :where(.kfShell,.panel,.kfWorkspace,.kfDetailShell,.printerFilesPanel,.discoveryPanel) :where(h1,h2,h3,h4,strong,b){text-shadow:none;color:inherit}
:root[data-theme] :where(button,input,select,textarea){font-family:inherit}

/* Stable application chrome */
:root[data-theme] .kfShell{
  grid-template-columns:210px minmax(0,1fr);
  background:var(--ui-bg)!important;
  color:var(--ui-text);
  overflow:hidden;
}
:root[data-theme] .kfAmbient{display:none!important}
:root[data-theme] .kfSidebar{
  padding:20px 14px;
  border-right:1px solid var(--ui-border)!important;
  background:var(--ui-surface)!important;
  box-shadow:none!important;
}
:root[data-theme] .kfSidebar:after,
:root[data-theme] .kfTopbar:after,
:root[data-theme] .kfTelemetryCard:before,
:root[data-theme] .kfTelemetryCard:after,
:root[data-theme] .kfToolsPage>button:after{display:none!important}
:root[data-theme] .kfBrand{height:50px;padding:0 8px;gap:11px;color:var(--ui-text);font-size:14px;letter-spacing:.025em}
:root[data-theme] .kfBrand b{color:var(--ui-text)!important;background:none!important;text-shadow:none!important}
:root[data-theme] .kfLogo{
  width:34px;height:34px;border:1px solid var(--ui-border)!important;border-radius:10px!important;
  background:var(--ui-surface-2)!important;box-shadow:none!important;
}
:root[data-theme] .kfSidebar nav{gap:5px;margin-top:18px}
:root[data-theme] .kfSidebar nav button{
  min-height:44px;padding:0 12px;border:1px solid transparent!important;border-radius:10px!important;
  background:transparent!important;color:var(--ui-muted)!important;font-size:13px;font-weight:600;
  transition:background-color .16s ease,color .16s ease,border-color .16s ease;
}
:root[data-theme] .kfSidebar nav button:before{display:none!important}
:root[data-theme] .kfSidebar nav button svg{width:18px;filter:none!important}
:root[data-theme] .kfSidebar nav button:hover{background:var(--ui-surface-2)!important;color:var(--ui-text)!important;border-color:var(--ui-border)!important}
:root[data-theme] .kfSidebar nav button.active{
  background:var(--ui-accent-soft)!important;color:var(--ui-accent)!important;border-color:transparent!important;box-shadow:none!important;
}
:root[data-theme] .kfMain{padding:18px 24px 26px;background:var(--ui-bg);color:var(--ui-text)}
:root[data-theme] .kfTopbar{
  min-height:70px;display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:start;gap:18px;
  padding:0 0 14px;border-bottom:1px solid var(--ui-border)!important;
}
:root[data-theme] .kfPageIdentity{min-width:0}
:root[data-theme] .kfCyberEyebrow{
  display:inline-flex!important;align-items:center;min-height:22px;margin:0 0 5px;padding:0 8px;border:1px solid var(--ui-border);
  border-radius:999px;background:var(--ui-surface);color:var(--ui-muted)!important;font-size:9px!important;font-weight:700!important;letter-spacing:.025em!important;
}
:root[data-theme] .kfCyberEyebrow.farmOnline{color:var(--ui-success)!important;border-color:color-mix(in srgb,var(--ui-success) 30%,var(--ui-border));background:var(--ui-success-soft)}
:root[data-theme] .kfPageIdentity h1{margin:0 0 3px;font-size:23px!important;font-weight:720;letter-spacing:-.025em!important;color:var(--ui-text)!important;text-shadow:none!important}
:root[data-theme] .kfPageIdentity p{margin:0;color:var(--ui-muted)!important;font-size:11px}
:root[data-theme] .kfTopActions{align-self:center;gap:8px}
:root[data-theme] .kfTopActions button,
:root[data-theme] .notificationBell{
  min-height:40px;border:1px solid var(--ui-border)!important;border-radius:10px!important;
  background:var(--ui-surface)!important;color:var(--ui-muted)!important;box-shadow:none!important;
}
:root[data-theme] .kfTopActions button:hover{border-color:var(--ui-border-strong)!important;color:var(--ui-text)!important;background:var(--ui-surface-2)!important}
:root[data-theme] .kfThemeToggle{padding:0 12px!important}
:root[data-theme] .kfThemeToggle span{font-size:11px;font-weight:650}
:root[data-theme] .kfWindowBar{background:var(--ui-surface)!important;border-color:var(--ui-border)!important;color:var(--ui-muted)!important;box-shadow:var(--ui-shadow-soft)!important}
:root[data-theme] .kfWindowControls{background:var(--ui-surface)!important}
:root[data-theme] .kfWindowControls button{border-color:var(--ui-border)!important;color:var(--ui-muted)!important}
:root[data-theme] .kfWindowControls button:hover{background:var(--ui-surface-2)!important;color:var(--ui-text)!important}

/* Clean startup */
:root[data-theme] .kfSplash{
  background:var(--ui-bg)!important;color:var(--ui-text)!important;
  animation:kfProductSplashExit .2s 1.25s ease forwards!important;
}
:root[data-theme] .kfSplashGrid,
:root[data-theme] .kfSplashScan,
:root[data-theme] .kfSplashLogo:before,
:root[data-theme] .kfSplashLogo:after,
:root[data-theme] .kfSplashLogo span{display:none!important}
:root[data-theme] .kfSplash>section{width:min(430px,88vw);padding:38px;border:1px solid var(--ui-border);border-radius:22px;background:var(--ui-surface);box-shadow:var(--ui-shadow)}
:root[data-theme] .kfSplashLogo{width:72px;height:72px;animation:none!important}
:root[data-theme] .kfSplashLogo img{width:72px;height:72px;border-radius:17px;filter:none!important}
:root[data-theme] .kfSplash p{margin:22px 0 7px;color:var(--ui-muted)!important;letter-spacing:.14em;animation:none!important}
:root[data-theme] .kfSplash h1{font-size:30px;letter-spacing:.035em;animation:none!important}
:root[data-theme] .kfSplash h1 b{color:var(--ui-accent)}
:root[data-theme] .kfSplashConnect{margin-top:24px;border-color:var(--ui-border);border-radius:10px;background:var(--ui-surface-2);color:var(--ui-muted);animation:none!important}
:root[data-theme] .kfSplashConnect strong{color:var(--ui-accent)}
:root[data-theme] .kfSplashConnect i{background:var(--ui-success);box-shadow:none;animation:none!important}
:root[data-theme] .kfSplashProgress{height:4px;border-radius:99px;background:var(--ui-surface-3)}
:root[data-theme] .kfSplashProgress i{border-radius:inherit;background:var(--ui-accent);box-shadow:none;animation:kfProductLoad 1.15s ease both!important}
:root[data-theme] .kfSplash small{color:var(--ui-subtle);animation:none!important}
@keyframes kfProductLoad{from{width:0}to{width:100%}}
@keyframes kfProductSplashExit{to{opacity:0;visibility:hidden}}

/* Information-only home dashboard */
:root[data-theme] .dashboardMain{height:100vh;overflow:hidden}
.infoDashboard{
  height:calc(100vh - 106px);min-height:0;display:flex;flex-direction:column;gap:11px;padding-top:13px;overflow:hidden;color:var(--ui-text);
}
.infoSummary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px}
.infoSummary>article{
  min-width:0;display:grid;grid-template-columns:42px minmax(0,1fr);grid-template-rows:auto auto auto;column-gap:11px;
  min-height:78px;padding:12px 14px;border:1px solid var(--ui-border);border-radius:14px;background:var(--ui-surface);box-shadow:var(--ui-shadow-soft);
}
.infoSummary>article>i{grid-row:1/4;width:40px;height:40px;display:grid;place-items:center;align-self:center;border-radius:12px;background:var(--ui-accent-soft);color:var(--ui-accent);font-style:normal}
.infoSummary>article>i svg{width:20px}
.infoSummary>article>span{align-self:end;color:var(--ui-muted);font-size:10px;font-weight:650}
.infoSummary>article>strong{font-size:22px;line-height:1.05;font-variant-numeric:tabular-nums}
.infoSummary>article>small{color:var(--ui-subtle);font-size:9px}
.infoSummary>article.online>i,.infoSummary>article.healthy>i{background:var(--ui-success-soft);color:var(--ui-success)}
.infoSummary>article.attention>i{background:var(--ui-warning-soft);color:var(--ui-warning)}
.infoAttention{
  min-height:50px;display:grid;grid-template-columns:22px minmax(0,1fr) auto 18px;align-items:center;gap:11px;
  padding:9px 13px;border:1px solid color-mix(in srgb,var(--ui-warning) 35%,var(--ui-border));border-radius:12px;background:var(--ui-warning-soft);color:var(--ui-warning);
}
.infoAttention>svg{width:20px}.infoAttention>svg:last-child{width:16px}
.infoAttention>div strong,.infoAttention>div span{display:block}
.infoAttention>div strong{font-size:11px}.infoAttention>div span{margin-top:2px;color:var(--ui-muted);font-size:9px}
.infoAttention em{font-size:9px;font-style:normal;font-weight:700}
.infoPrintersSection{flex:1;min-height:0;display:flex;flex-direction:column}
.infoPrintersSection>header,.infoReport>header{min-height:39px;display:flex;align-items:center;justify-content:space-between;gap:16px}
.infoPrintersSection>header h2,.infoReport>header h2{margin:0;font-size:14px;letter-spacing:-.01em}
.infoPrintersSection>header p,.infoReport>header p{margin:2px 0 0;color:var(--ui-muted);font-size:9px}
.infoPrintersSection>header button,.infoReport>header button{
  display:flex;align-items:center;gap:4px;border:0;background:transparent;color:var(--ui-accent);font-size:10px;font-weight:700;padding:6px;
}
.infoPrintersSection>header button svg,.infoReport>header button svg{width:14px}
.infoPrinterGrid{flex:1;min-height:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));grid-template-rows:repeat(2,minmax(0,1fr));gap:10px}
.infoPrinterCard{
  position:relative;min-width:0;min-height:0;display:grid;grid-template-columns:104px minmax(0,1fr);gap:10px;
  padding:11px 30px 11px 10px;border:1px solid var(--ui-border);border-radius:14px;background:var(--ui-surface);color:var(--ui-text);
  text-align:left;box-shadow:var(--ui-shadow-soft);overflow:hidden;transition:border-color .15s ease,box-shadow .15s ease;
}
.infoPrinterCard:hover{border-color:var(--ui-border-strong);box-shadow:var(--ui-shadow)}
.infoPrinterCard>img{width:100%;height:100%;max-height:126px;align-self:center;object-fit:contain;filter:none!important;mix-blend-mode:normal!important}
.infoPrinterBody{min-width:0;display:flex;flex-direction:column;justify-content:center;gap:7px}
.infoPrinterBody>header{display:flex;align-items:flex-start;justify-content:space-between;gap:7px}
.infoPrinterBody>header>div{min-width:0}.infoPrinterBody>header strong,.infoPrinterBody>header small{display:block}
.infoPrinterBody>header strong{overflow:hidden;font-size:12px;white-space:nowrap;text-overflow:ellipsis}
.infoPrinterBody>header small{margin-top:2px;color:var(--ui-subtle);font-size:8px}
.infoState{flex:none;display:inline-flex;align-items:center;gap:5px;max-width:138px;padding:4px 7px;border-radius:999px;background:var(--ui-surface-3);color:var(--ui-muted);font-size:8px;font-weight:750;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.infoState i{width:6px;height:6px;flex:none;border-radius:50%;background:currentColor}
.infoState.printing,.infoState.ready{background:var(--ui-success-soft);color:var(--ui-success)}
.infoState.warning{background:var(--ui-warning-soft);color:var(--ui-warning)}
.infoState.danger{background:var(--ui-danger-soft);color:var(--ui-danger)}
.infoJob{min-width:0;display:flex;align-items:center;gap:6px;color:var(--ui-muted)}
.infoJob svg{width:13px;flex:none}.infoJob b{overflow:hidden;color:var(--ui-text);font-size:9px;font-weight:600;white-space:nowrap;text-overflow:ellipsis}
.infoProgress{display:grid;grid-template-columns:minmax(0,1fr) 32px;align-items:center;gap:8px}
.infoProgress>i{height:5px;overflow:hidden;border-radius:99px;background:var(--ui-surface-3);font-style:normal}
.infoProgress>i b{display:block;height:100%;border-radius:inherit;background:var(--ui-accent)}
.infoProgress>strong{text-align:right;font-size:10px;font-variant-numeric:tabular-nums}
.infoPrinterBody>footer{display:flex;align-items:center;justify-content:space-between;gap:8px;color:var(--ui-muted);font-size:8px}
.infoPrinterBody>footer span{min-width:0;display:flex;align-items:center;gap:4px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
.infoPrinterBody>footer svg{width:11px;flex:none}
.infoOpen{position:absolute;right:9px;top:50%;width:15px;color:var(--ui-subtle);transform:translateY(-50%)}
.infoEmpty{grid-column:1/-1;grid-row:1/-1;display:grid;place-items:center;align-content:center;gap:8px;border:1px dashed var(--ui-border-strong);border-radius:14px;background:var(--ui-surface);color:var(--ui-muted);text-align:center}
.infoEmpty>svg{width:34px}.infoEmpty strong{color:var(--ui-text)}.infoEmpty button{padding:8px 12px;border:0;border-radius:9px;background:var(--ui-accent);color:#fff}
.infoReport{flex:none}
.infoReportBody{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(260px,.85fr);gap:10px}
.infoMetrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}
.infoMetrics>article{
  min-width:0;display:grid;grid-template-columns:24px minmax(0,1fr);grid-template-rows:auto auto auto;gap:1px 7px;
  min-height:90px;padding:10px;border:1px solid var(--ui-border);border-radius:12px;background:var(--ui-surface);
}
.infoMetrics>article>svg{grid-row:1/4;width:18px;color:var(--ui-accent)}
.infoMetrics>article>span{color:var(--ui-muted);font-size:8px}
.infoMetrics>article>strong{font-size:18px;font-variant-numeric:tabular-nums}
.infoMetrics>article>small{overflow:hidden;color:var(--ui-subtle);font-size:7.5px;white-space:nowrap;text-overflow:ellipsis}
.infoTrend{min-height:90px;padding:10px 12px 8px;border:1px solid var(--ui-border);border-radius:12px;background:var(--ui-surface)}
.infoTrend>div:first-child{display:flex;align-items:center;justify-content:space-between;font-size:9px}.infoTrend>div:first-child span{color:var(--ui-muted);font-size:8px}
.infoBars{height:57px;display:flex;align-items:flex-end;gap:4px;margin-top:6px;border-bottom:1px solid var(--ui-border)}
.infoBars>i{position:relative;flex:1;min-height:2px;border-radius:3px 3px 0 0;background:var(--ui-accent);opacity:.86;font-style:normal}
.infoBars>i span{position:absolute;left:50%;bottom:-15px;color:var(--ui-subtle);font-size:6px;white-space:nowrap;transform:translateX(-50%)}

/* Shared cards and controls across all tabs */
:root[data-theme] :where(
  .panel,.settingsModal,.kfPrinterCard,.kfToolsPage>button,.queuePrinter,.queueJob,
  .runtimeCard,.analyticsCards>div,.maintenancePresets article,.maintenanceList article,
  .healthResults article,.setupSection,.printerSetupPreview,.backupBox,.updaterBox,
  .userTable>div,.auditTable>div,.reportTable,.smartPanel,.localFileCard,.localFolderCard
){
  border-color:var(--ui-border)!important;border-radius:14px!important;
  background:var(--ui-surface)!important;color:var(--ui-text)!important;
  box-shadow:var(--ui-shadow-soft)!important;clip-path:none!important;
}
:root[data-theme] :where(.panelHead,.kfWorkspaceHead,.kfBoxTitle,.queueHead,.printerFilesHead){
  border-color:var(--ui-border)!important;background:var(--ui-surface)!important;color:var(--ui-text)!important;
}
:root[data-theme] .panelHead{padding:17px 18px}
:root[data-theme] .panelHead h2{font-size:20px;letter-spacing:-.02em!important}
:root[data-theme] .panelHead p{color:var(--ui-muted)!important}
:root[data-theme] .modalBackdrop,
:root[data-theme] .cameraBackdrop,
:root[data-theme] .printerFileDialogBackdrop{
  background:var(--ui-overlay)!important;backdrop-filter:none!important;
}
:root[data-theme] .panel{border:1px solid var(--ui-border)!important;background:var(--ui-surface)!important;box-shadow:var(--ui-shadow)!important}
:root[data-theme] :where(input,select,textarea),
:root[data-theme] :where(.panel input,.panel select,.panel textarea,.settingsModal input,.settingsModal select,.settingsModal textarea){
  border:1px solid var(--ui-border)!important;border-radius:9px!important;background:var(--ui-surface-2)!important;color:var(--ui-text)!important;box-shadow:none!important;outline:none;
}
:root[data-theme] :where(input,select,textarea):focus{
  border-color:var(--ui-accent)!important;box-shadow:0 0 0 3px color-mix(in srgb,var(--ui-accent) 16%,transparent)!important;
}
:root[data-theme] :where(.panel button,.settingsModal button,.kfWorkspace button,.printerFilesPanel button,.discoveryPanel button,.button){
  border-color:var(--ui-border)!important;border-radius:9px!important;background:var(--ui-surface-2)!important;color:var(--ui-text)!important;box-shadow:none!important;
}
:root[data-theme] :where(.panel button,.settingsModal button,.kfWorkspace button,.printerFilesPanel button,.discoveryPanel button,.button):hover:not(:disabled){
  border-color:var(--ui-border-strong)!important;background:var(--ui-surface-3)!important;
}
:root[data-theme] :where(button.primary,.primary,.kfUpload,.printerFilesPanel button.primary){
  border-color:var(--ui-accent)!important;background:var(--ui-accent)!important;color:#fff!important;box-shadow:none!important;
}
:root[data-theme] :where(button.primary,.primary,.kfUpload):hover:not(:disabled){background:var(--ui-accent-hover)!important}
:root[data-theme] :where(button.danger,.danger,.plainDanger){border-color:color-mix(in srgb,var(--ui-danger) 35%,var(--ui-border))!important;background:var(--ui-danger-soft)!important;color:var(--ui-danger)!important}
:root[data-theme] .round{width:38px;height:38px;padding:0!important;display:grid!important;place-items:center}
:root[data-theme] .prodTabs{gap:6px;padding:8px 14px;border-color:var(--ui-border)!important;background:var(--ui-surface)!important}
:root[data-theme] .prodTabs button{border-radius:9px!important;background:transparent!important;color:var(--ui-muted)!important}
:root[data-theme] .prodTabs button.active{border-color:transparent!important;background:var(--ui-accent-soft)!important;color:var(--ui-accent)!important;box-shadow:none!important}
:root[data-theme] .prodToolbar{border-color:var(--ui-border)!important;background:var(--ui-surface-2)!important}
:root[data-theme] .muted{color:var(--ui-muted)!important}

/* Printers tab */
:root[data-theme] .kfPrinterPageActions{margin-top:14px}
:root[data-theme] .kfPrinterPageActions button{border:1px solid var(--ui-border);border-radius:9px;background:var(--ui-surface);color:var(--ui-text);box-shadow:none}
:root[data-theme] .kfPrinterPageActions button.primary{background:var(--ui-accent);color:#fff}
:root[data-theme] .kfPrinterGrid{grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-top:14px}
:root[data-theme] .kfTelemetryCard{
  min-height:390px;padding:14px;border:1px solid var(--ui-border)!important;border-radius:16px!important;
  background:var(--ui-surface)!important;color:var(--ui-text);box-shadow:var(--ui-shadow-soft)!important;clip-path:none!important;
}
:root[data-theme] .kfTelemetryCard:hover{border-color:var(--ui-border-strong)!important;box-shadow:var(--ui-shadow)!important;transform:none!important}
:root[data-theme] .kfTelemetryHead span,
:root[data-theme] .kfTelemetryJob span,
:root[data-theme] .kfTelemetryFoot span{color:var(--ui-muted)!important;letter-spacing:.035em!important}
:root[data-theme] .kfTelemetryHead h2{color:var(--ui-text)!important;text-shadow:none!important}
:root[data-theme] .kfTelemetryMachine{
  overflow:hidden!important;border:1px solid var(--ui-border);border-radius:12px;background:var(--ui-surface-2)!important;clip-path:none!important;
}
:root[data-theme] .kfTelemetryMachine:before,
:root[data-theme] .kfTelemetryMachine:after,
:root[data-theme] .kfHologramScan{display:none!important}
:root[data-theme] .kfTelemetryMachine img{
  height:200px!important;filter:none!important;mix-blend-mode:normal!important;transform:none!important;transition:none!important;
}
:root[data-theme] .kfTelemetryMachine>strong{color:var(--ui-accent)!important;text-shadow:none!important}
:root[data-theme] .kfTelemetryMachine>span{text-shadow:none!important;color:var(--ui-muted)!important}
:root[data-theme] .kfTelemetryTemp{border-color:var(--ui-border)!important}
:root[data-theme] .kfTelemetryTemp svg{background:none!important}
:root[data-theme] .kfTelemetryStats>div{border:1px solid var(--ui-border)!important;border-radius:9px;background:var(--ui-surface-2)!important}
:root[data-theme] .kfTelemetryProgress{height:5px;background:var(--ui-surface-3)!important}
:root[data-theme] .kfTelemetryProgress i{background:var(--ui-accent)!important;box-shadow:none!important}
:root[data-theme] .kfTelemetryProgress em{display:none}
:root[data-theme] .kfTelemetryActions button{border-color:var(--ui-border)!important;border-radius:8px!important;background:var(--ui-surface-2)!important;color:var(--ui-text)!important}
:root[data-theme] .kfTelemetryActions .primary{background:var(--ui-accent)!important;color:#fff!important}
:root[data-theme] .kfDelete{z-index:9;opacity:1;top:12px;left:12px;border:1px solid color-mix(in srgb,var(--ui-danger) 30%,var(--ui-border));border-radius:9px;background:var(--ui-danger-soft);color:var(--ui-danger);box-shadow:none}

/* Tools tab */
:root[data-theme] .kfToolsPage{grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
:root[data-theme] .kfToolsPage>button{min-height:110px;padding:16px;transition:border-color .15s ease,background-color .15s ease!important}
:root[data-theme] .kfToolsPage>button:hover{border-color:var(--ui-border-strong)!important;background:var(--ui-surface-2)!important;transform:none!important}
:root[data-theme] .kfToolsPage>button>span{border:0!important;border-radius:11px!important;background:var(--ui-accent-soft)!important;color:var(--ui-accent)!important;box-shadow:none!important}
:root[data-theme] .kfToolsPage b{color:var(--ui-text)}:root[data-theme] .kfToolsPage small{color:var(--ui-muted)}

/* Full printer workspace */
