}
:root[data-theme] .kfDetailSidebar:after{display:none!important}
:root[data-theme] .kfDetailBrand{border-color:var(--ui-border)!important}
:root[data-theme] .kfDetailBrand span{color:var(--ui-accent)!important;text-shadow:none!important}
:root[data-theme] .kfDetailSidebar nav button{border-color:transparent!important;background:transparent!important;color:var(--ui-muted)!important}
:root[data-theme] .kfDetailSidebar nav button.active{border-left-color:var(--ui-accent)!important;background:var(--ui-accent-soft)!important;color:var(--ui-accent)!important;box-shadow:none!important}
:root[data-theme] .kfDetailSidebar nav button svg{filter:none!important}
:root[data-theme] .kfDetailConnection,
:root[data-theme] .kfDetailBack{border-color:var(--ui-border)!important;border-radius:10px;background:var(--ui-surface-2)!important;color:var(--ui-text)!important}
