:root[data-theme] .kfCyberPanel,
:root[data-theme] .kfDetailHero,
:root[data-theme] .kfDetailRight>section,
:root[data-theme] .kfDetailControls>section{
  border-color:var(--ui-border)!important;border-radius:14px!important;background:var(--ui-surface)!important;color:var(--ui-text)!important;box-shadow:var(--ui-shadow-soft)!important;clip-path:none!important;
}
:root[data-theme] .kfCyberPanel:before,
:root[data-theme] .kfCyberPanel:after{display:none!important}
:root[data-theme] .kfDetailHeroStage{background:var(--ui-surface-2)!important;background-image:none!important;mask-image:none!important}
:root[data-theme] .kfDetailHeroStage>img{filter:none!important}
:root[data-theme] .kfDetailHero h1{color:var(--ui-text)!important;text-shadow:none!important}
:root[data-theme] .kfDetailProgressHalo{
  width:220px!important;height:112px!important;aspect-ratio:auto!important;border:1px solid var(--ui-border);border-radius:14px!important;
  background:var(--ui-surface)!important;filter:none!important;box-shadow:var(--ui-shadow-soft)!important;
}
:root[data-theme] .kfDetailProgressHalo:before,
:root[data-theme] .kfDetailProgressHalo:after{display:none!important}
:root[data-theme] .kfDetailProgressHalo strong{color:var(--ui-accent);font-size:44px!important}
:root[data-theme] .kfDetailProgressHalo span{color:var(--ui-muted)!important}
:root[data-theme] .kfDetailHeroMetrics>div,
:root[data-theme] .kfDetailCurrentJob,
:root[data-theme] .kfDetailTempCard,
:root[data-theme] .kfDetailConsole,
:root[data-theme] .kfDetailMacros{
