:root[data-theme] .kfDetailJobProgress>i{background:var(--ui-surface-3)!important;border-radius:99px}
:root[data-theme] .kfDetailJobProgress>i b{background:var(--ui-accent)!important;box-shadow:none!important}
:root[data-theme] .kfDetailConsoleLines,
:root[data-theme] .kfDiagnostics pre{background:var(--ui-surface-2)!important;color:var(--ui-text)!important;text-shadow:none!important;border-color:var(--ui-border)!important}

