:root[data-theme] .discoveryResults>article{
  border-color:var(--ui-border)!important;border-radius:11px!important;background:var(--ui-surface-2)!important;color:var(--ui-text)!important;clip-path:none!important;
}
:root[data-theme] .discoveryDeviceState{border-color:var(--ui-border)!important;border-radius:10px;background:var(--ui-accent-soft)!important;color:var(--ui-accent)!important}
:root[data-theme] .discoveryProgress{border-color:var(--ui-border)!important;background:var(--ui-surface-2)!important}
:root[data-theme] .discoveryProgress progress::-webkit-progress-value{background:var(--ui-accent)!important;box-shadow:none!important}

/* Queue, reports, production and settings */
:root[data-theme] .queuePrinter,
:root[data-theme] .queueJob,
:root[data-theme] .analyticsCards>div,
:root[data-theme] .analyticsTable>div,
:root[data-theme] .reportTable>div,
:root[data-theme] .scheduleList>div,
:root[data-theme] .smartJobs>article,
:root[data-theme] .spoolGrid>article,
:root[data-theme] .spoolmanGrid>article{
  border-color:var(--ui-border)!important;border-radius:11px!important;background:var(--ui-surface-2)!important;color:var(--ui-text)!important;box-shadow:none!important;
}
