/* ========================================================================== 
   PRODUCTIVITY UI — WHITE-FIRST CORRECTION
   ========================================================================== */

/* The dashboard summary belongs to the page header, as in the approved layout. */
:root[data-theme] .dashboardShell .kfTopbar{
  grid-template-columns:minmax(225px,.72fr) minmax(520px,1.55fr) auto;
  align-items:center;
}
.dashboardTopSummary{min-width:0;display:grid;grid-template-columns:repeat(4,minmax(116px,1fr));gap:9px}
.dashboardTopSummary>article{
  min-width:0;min-height:58px;display:grid;grid-template-columns:34px minmax(0,1fr);grid-template-rows:auto auto;
  align-content:center;column-gap:9px;padding:8px 10px;border:1px solid var(--ui-border);border-radius:12px;
  background:var(--ui-surface);box-shadow:var(--ui-shadow-soft);
}
.dashboardTopSummary>article>i{grid-row:1/3;width:32px;height:32px;display:grid;place-items:center;align-self:center;border-radius:50%;background:var(--ui-accent-soft);color:var(--ui-accent);font-style:normal}
.dashboardTopSummary>article>i svg{width:17px}.dashboardTopSummary>article>span{align-self:end;overflow:hidden;color:var(--ui-muted);font-size:8px;font-weight:650;white-space:nowrap;text-overflow:ellipsis}
.dashboardTopSummary>article>strong{align-self:start;font-size:17px;line-height:1.1;font-variant-numeric:tabular-nums}
.dashboardTopSummary>article.online>i,.dashboardTopSummary>article.healthy>i{background:var(--ui-success-soft);color:var(--ui-success)}
.dashboardTopSummary>article.attention>i{background:var(--ui-warning-soft);color:var(--ui-warning)}

/* Explicit two-position theme control: the highlighted side is the active theme. */
.kfThemeSwitch{display:flex;align-items:center;padding:3px;border:1px solid var(--ui-border);border-radius:11px;background:var(--ui-surface);box-shadow:var(--ui-shadow-soft)}
:root[data-theme] .kfThemeSwitch button{
  min-height:32px!important;padding:0 8px!important;border:0!important;border-radius:8px!important;background:transparent!important;color:var(--ui-muted)!important;box-shadow:none!important;
}
:root[data-theme] .kfThemeSwitch button svg{width:15px}.kfThemeSwitch button span{font-size:9px;font-weight:650}
:root[data-theme] .kfThemeSwitch button.active{background:var(--ui-accent-soft)!important;color:var(--ui-accent)!important}

/* Approved information dashboard. */
.infoDashboard{height:calc(100vh - 106px)}
