/* Printer management is now a clean equipment list — no sparklines or decorative telemetry graphs. */
:root[data-theme] .kfPrinterGrid{grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:12px;margin-top:14px}
.printerManagerCard{
  min-width:0;display:flex;flex-direction:column;gap:11px;padding:14px;border:1px solid var(--ui-border);border-radius:14px;
  background:var(--ui-surface);color:var(--ui-text);box-shadow:var(--ui-shadow-soft);cursor:pointer;transition:border-color .15s ease,box-shadow .15s ease;
}
.printerManagerCard:hover{border-color:var(--ui-border-strong);box-shadow:var(--ui-shadow)}
.printerManagerHead{min-width:0;display:grid;grid-template-columns:78px minmax(0,1fr) auto;align-items:center;gap:11px}
.printerManagerHead>img{width:78px;height:76px;object-fit:contain;filter:none!important}
.printerManagerIdentity{min-width:0}.printerManagerIdentity>span,.printerManagerIdentity>small{display:block;overflow:hidden;color:var(--ui-subtle);font-size:8px;white-space:nowrap;text-overflow:ellipsis}
.printerManagerChannel{display:inline-flex;margin-left:6px;padding:2px 5px;border:1px solid var(--ui-border-strong);border-radius:999px;background:var(--ui-accent-soft);color:var(--ui-accent);font-size:7px;font-style:normal;font-weight:800;letter-spacing:.03em;vertical-align:middle}
.printerManagerIdentity h2{overflow:hidden;margin:3px 0 4px;color:var(--ui-text);font-size:15px;letter-spacing:-.02em;white-space:nowrap;text-overflow:ellipsis}
.printerManagerState{align-self:start;display:inline-flex;align-items:center;gap:5px;max-width:120px;padding:5px 8px;border-radius:999px;background:var(--ui-surface-3);color:var(--ui-muted);font-size:8px;font-weight:750;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.printerManagerState i{width:6px;height:6px;flex:none;border-radius:50%;background:currentColor}.printerManagerState.ready,.printerManagerState.printing{background:var(--ui-success-soft);color:var(--ui-success)}.printerManagerState.warning{background:var(--ui-warning-soft);color:var(--ui-warning)}.printerManagerState.danger{background:var(--ui-danger-soft);color:var(--ui-danger)}
.printerManagerJob{min-width:0;display:grid;grid-template-columns:24px minmax(0,1fr) auto;align-items:center;gap:8px;padding:9px 10px;border-radius:10px;background:var(--ui-surface-2)}
.printerManagerJob>svg{width:17px;color:var(--ui-accent)}.printerManagerJob div{min-width:0}.printerManagerJob span,.printerManagerJob b{display:block}.printerManagerJob span{color:var(--ui-muted);font-size:8px}.printerManagerJob b{overflow:hidden;margin-top:2px;font-size:9px;white-space:nowrap;text-overflow:ellipsis}.printerManagerJob>strong{font-size:11px}
.printerManagerProgress{height:5px;overflow:hidden;border-radius:99px;background:var(--ui-surface-3)}.printerManagerProgress i{display:block;height:100%;border-radius:inherit;background:var(--ui-accent)}
.printerManagerFacts{display:flex;align-items:center;gap:14px;color:var(--ui-muted);font-size:8px}.printerManagerFacts span{display:flex;align-items:center;gap:4px;white-space:nowrap}.printerManagerFacts svg{width:13px}.printerManagerFacts b{color:var(--ui-text);font-weight:700}
.telemetryAge.stale,.telemetryHeaderState.stale{color:var(--ui-warning)!important}.telemetryAge.expired,.telemetryAge.unavailable,.telemetryHeaderState.expired,.telemetryHeaderState.unavailable{color:var(--ui-danger)!important}.telemetryHeaderState{margin-left:auto;color:var(--ui-muted);font-size:8px;font-weight:700}
.printerManagerActions{display:flex;align-items:center;gap:6px;margin-top:auto;padding-top:10px;border-top:1px solid var(--ui-border)}
:root[data-theme] .printerManagerActions button{min-height:32px;display:flex;align-items:center;justify-content:center;gap:5px;padding:0 8px;border:1px solid var(--ui-border);border-radius:8px;background:var(--ui-surface);color:var(--ui-muted);font-size:8px;box-shadow:none}
