:root[data-theme] .kfCardWrap>.kfDelete{top:9px;left:9px;width:32px;height:32px;display:grid;place-items:center;padding:0;border-radius:50%;opacity:1;background:var(--ui-danger-soft);color:var(--ui-danger);transition:background-color .15s ease,color .15s ease,transform .15s ease}
