/* ==========================================================================
   CONTRAST AND TOOLS CASCADE FIX
   The legacy light-theme HUD used a more specific !important selector and
   kept the tools black. These explicit final selectors intentionally outrank
   that legacy layer and keep secondary printer data readable.
   ========================================================================== */
:root[data-theme="light"] .kfToolsPage>button{
  min-height:116px!important;padding:18px!important;
  border:1.5px solid var(--ui-border)!important;border-radius:14px!important;
