  border-color:var(--ui-accent)!important;background:var(--ui-accent-soft)!important;box-shadow:var(--ui-shadow)!important;
}
:root[data-theme] .kfToolsPage>button:before,
:root[data-theme] .kfToolsPage>button:after{content:none!important;display:none!important}
:root[data-theme="light"] .kfToolsPage>button:disabled{opacity:.82!important;cursor:not-allowed}
:root[data-theme="light"] .kfToolsPage>button>span{
  flex:none;width:52px!important;height:52px!important;border:1px solid #c9dbf7!important;border-radius:13px!important;
  background:var(--ui-accent-soft)!important;background-image:none!important;color:var(--ui-accent)!important;clip-path:none!important;
}
