/* ==========================================================================
   READABILITY AND ACTIONABLE ATTENTION FIX V8
   Strong outlines, legible labels and a notification that can be opened or
   dismissed. This layer stays last so the retired dark HUD cannot leak back.
   ========================================================================== */
:root[data-theme="light"]{
  --readable-outline:#aab7c7;
  --readable-outline-soft:#c2ccd8;
  --readable-secondary:#3f4b5d;
}
:root[data-theme="dark"]{
  --readable-outline:#536071;
  --readable-outline-soft:#424c5b;
  --readable-secondary:#c8d0db;
}

/* Dashboard notification: the main area opens the affected printer and the
   square button always dismisses the current issue set. */
.infoAttention{
  min-height:58px!important;display:grid!important;grid-template-columns:minmax(0,1fr) 42px!important;
  gap:4px!important;padding:0 6px 0 0!important;border:2px solid color-mix(in srgb,var(--ui-warning) 55%,var(--readable-outline))!important;
  border-radius:12px!important;background:var(--ui-warning-soft)!important;overflow:hidden!important;
}
.infoAttentionOpen{
  min-width:0;min-height:54px;display:grid;grid-template-columns:25px minmax(0,1fr) auto 18px;align-items:center;gap:11px;
  padding:8px 8px 8px 14px;border:0;background:transparent;color:var(--ui-warning);text-align:left;cursor:pointer;
}
.infoAttentionOpen:hover{background:color-mix(in srgb,var(--ui-warning) 8%,transparent)}
.infoAttentionOpen:focus-visible,.infoAttentionClose:focus-visible{outline:3px solid color-mix(in srgb,var(--ui-accent) 62%,transparent);outline-offset:-3px}
.infoAttentionOpen>svg{width:21px;height:21px;flex:none}
.infoAttentionOpen>svg:last-child{width:17px;height:17px}
.infoAttentionText{min-width:0;display:block}
.infoAttentionText strong,.infoAttentionText>span{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.infoAttentionText strong{color:var(--ui-text)!important;font-size:13px!important;font-weight:800!important;line-height:1.2}
.infoAttentionText>span{margin-top:3px;color:var(--readable-secondary)!important;font-size:11px!important;font-weight:650!important}
.infoAttentionOpen em{color:var(--ui-warning);font-size:10.5px!important;font-style:normal;font-weight:800!important;white-space:nowrap}
.infoAttentionClose{
  width:38px;height:38px;display:grid;place-items:center;align-self:center;border:2px solid color-mix(in srgb,var(--ui-warning) 45%,var(--readable-outline));
  border-radius:10px;background:var(--ui-surface);color:var(--ui-warning);cursor:pointer;
}
.infoAttentionClose:hover{border-color:var(--ui-warning);background:color-mix(in srgb,var(--ui-warning) 12%,var(--ui-surface))}
.infoAttentionClose svg{width:19px;height:19px;stroke-width:2.8}

/* Dashboard cards remain three per row, but their hierarchy is readable from
   a normal laptop viewing distance. */
.infoSummary>article,.infoPrinterCard,.infoMetrics>article,.infoTrend{
  border:2px solid var(--readable-outline)!important;box-shadow:0 2px 8px rgba(15,23,42,.09)!important;
}
.infoSummary>article>span{color:var(--readable-secondary)!important;font-size:10.5px!important;font-weight:750!important}
.infoSummary>article>strong{font-weight:820!important}
.infoSummary>article>small{color:var(--readable-secondary)!important;font-size:9.5px!important;font-weight:650!important}
.infoPrinterCard{padding-right:34px!important}
.infoPrinterCard:hover{border-color:var(--ui-accent)!important;box-shadow:0 6px 18px rgba(15,23,42,.14)!important}
.infoPrinterBody>header strong{font-size:16px!important;font-weight:820!important;line-height:1.15!important}
.infoPrinterBody>header small{color:var(--readable-secondary)!important;font-size:10.5px!important;font-weight:700!important}
.infoState{max-width:142px!important;padding:5px 9px!important;font-size:10px!important;font-weight:820!important}
