/* ==========================================================================
   ALL-WHITE WORKSPACES AND HIDDEN SCROLLBARS V9
   The original interface still contained isolated black HUD surfaces in the
   light theme. Keep scrolling functional, but remove the permanently visible
   scrollbar chrome and make every work dialog a crisp white productivity UI.
   ========================================================================== */

/* Scroll with the wheel, touchpad, keyboard and touch as before. Only the
   always-visible WebView/Windows scrollbar track is hidden. */
html[data-theme]{scrollbar-width:none!important;scrollbar-gutter:auto!important}
html[data-theme]::-webkit-scrollbar,
:root[data-theme] *::-webkit-scrollbar{width:0!important;height:0!important;display:none!important}
:root[data-theme] *{scrollbar-width:none!important}

:root[data-theme="light"]{
  --workspace-white:#ffffff;
  --workspace-soft:#f5f7fa;
  --workspace-soft-blue:#eef5ff;
  --workspace-outline:#9eacbd;
  --workspace-outline-soft:#c3ccd8;
  --workspace-text:#101827;
  --workspace-muted:#445166;
  --workspace-subtle:#69768a;
}

/* File manager shell and the two storage tabs. */
:root[data-theme="light"] .printerFilesPanel{
  border:2px solid var(--workspace-outline)!important;
  background:var(--workspace-white)!important;background-image:none!important;
  color:var(--workspace-text)!important;box-shadow:0 18px 55px rgba(15,23,42,.17)!important;
}
:root[data-theme="light"] .printerFilesPanel :where(.printerFilesHead,.printerFilesSourceTabs,.printerFilesCommandBar){
  border-color:var(--workspace-outline-soft)!important;background:var(--workspace-white)!important;background-image:none!important;
}
:root[data-theme="light"] .printerFilesHead{border-bottom-width:2px!important;box-shadow:none!important}
:root[data-theme="light"] .printerFilesHead:before,
:root[data-theme="light"] .printerFilesNode:after,
:root[data-theme="light"] .printerFilesStats>div:after,
:root[data-theme="light"] .printerFilesStats>div:before,
:root[data-theme="light"] .printerFilesDrop:before,
:root[data-theme="light"] .printerFilesList>article.printerFileCard:before,
:root[data-theme="light"] .printerFilesList>article.printerFileCard:after{display:none!important}
:root[data-theme="light"] .printerFilesTitle>i,
:root[data-theme="light"] .localLibraryHero>div:first-child>i,
:root[data-theme="light"] .localLibraryImport>div:first-child>i{
  border:2px solid color-mix(in srgb,var(--ui-accent) 36%,var(--workspace-outline))!important;
  border-radius:11px!important;background:var(--workspace-soft-blue)!important;background-image:none!important;
  color:var(--ui-accent)!important;box-shadow:none!important;clip-path:none!important;
}
:root[data-theme="light"] .printerFilesTitle small,
:root[data-theme="light"] .localLibraryHero small,
:root[data-theme="light"] .localLibraryImport small{color:var(--ui-accent)!important;font-size:9px!important;font-weight:850!important}
:root[data-theme="light"] .printerFilesTitle h2{color:var(--workspace-text)!important;font-size:22px!important;font-weight:850!important}
:root[data-theme="light"] .printerFilesTitle p{color:var(--workspace-muted)!important;font-size:11px!important;font-weight:650!important}
:root[data-theme="light"] .printerFilesHeadActions>button,
:root[data-theme="light"] .printerFilesConnection{
  border:2px solid var(--workspace-outline)!important;border-radius:9px!important;background:var(--workspace-white)!important;
  color:var(--workspace-text)!important;font-size:10.5px!important;font-weight:750!important;clip-path:none!important;box-shadow:none!important;
}
:root[data-theme="light"] .printerFilesConnection{border-color:#78b592!important;background:#eefaf2!important;color:#15723c!important}
:root[data-theme="light"] .printerFilesConnection.state-error{border-color:#e29aa3!important;background:#fff1f2!important;color:#b42336!important}
:root[data-theme="light"] .printerFilesConnection.state-offline{border-color:var(--workspace-outline)!important;background:var(--workspace-soft)!important;color:var(--workspace-muted)!important}
:root[data-theme="light"] .printerFilesSourceTabs{gap:8px!important;padding-block:9px!important;border-bottom:2px solid var(--workspace-outline-soft)!important}
:root[data-theme="light"] .printerFilesSourceTabs>button{
  border:2px solid var(--workspace-outline)!important;border-radius:11px!important;background:var(--workspace-white)!important;background-image:none!important;
  color:var(--workspace-muted)!important;box-shadow:none!important;
}
:root[data-theme="light"] .printerFilesSourceTabs>button.active{border-color:var(--ui-accent)!important;background:var(--workspace-soft-blue)!important;color:var(--ui-accent)!important}
