:root[data-theme="light"] .printerFilesNode strong,
:root[data-theme="light"] .printerFilesDropCopy b{color:var(--workspace-text)!important;font-size:13px!important;font-weight:820!important}
:root[data-theme="light"] .printerFilesNode em,
:root[data-theme="light"] .printerFilesDropCopy em{color:var(--workspace-muted)!important;font-size:10px!important;font-weight:650!important}
:root[data-theme="light"] .printerFilesStats>div{background:var(--workspace-soft)!important}
:root[data-theme="light"] .printerFilesStats>div>svg{color:var(--ui-accent)!important;filter:none!important}
:root[data-theme="light"] .printerFilesStats strong{color:var(--workspace-text)!important;font-size:18px!important;font-weight:850!important}
:root[data-theme="light"] .printerFilesStats small{color:var(--workspace-muted)!important;font-size:9px!important;font-weight:780!important}
:root[data-theme="light"] .printerFilesStats em{color:var(--workspace-subtle)!important;font-size:8.5px!important;font-weight:650!important}
:root[data-theme="light"] .printerFilesUploadButton,
:root[data-theme="light"] .localLibraryImport>label.button{
