:root[data-theme="light"] .printerFileProject select{
  border:2px solid var(--workspace-outline)!important;border-radius:9px!important;background:var(--workspace-white)!important;
  color:var(--workspace-text)!important;font-size:10.5px!important;font-weight:650!important;
