/* ==========================================================================
   TARGETED WHITE UI CORRECTIONS V10
   Final screenshot-driven fixes for dispatcher, maintenance, diagnostics,
   production cost and the compact farm printer cards.
   ========================================================================== */

/* The light theme must remain genuinely white and readable even when an old
   HUD selector carries !important.  Dark graphite outlines are deliberate:
   they stay visible on a low-contrast laptop display without adding shadows. */
:root[data-theme="light"]{
  --workspace-white:#ffffff;
  --workspace-soft:#f4f6f8;
  --workspace-soft-blue:#edf5ff;
  --workspace-outline:#536174;
  --workspace-outline-soft:#aab4c1;
  --workspace-text:#05070b;
  --workspace-muted:#273344;
  --workspace-subtle:#4e5b6d;
}
:root[data-theme="light"] :where(.smartPanel,.maintenancePanel,.healthPanel,.productionPanel){
  border:2px solid #263548!important;background:#fff!important;background-image:none!important;color:#05070b!important;
}
:root[data-theme="light"] :where(.smartPanel,.maintenancePanel,.healthPanel,.productionPanel) .panelHead{
  border-bottom:2px solid #263548!important;background:#fff!important;background-image:none!important;color:#05070b!important;
}
:root[data-theme="light"] :where(.smartPanel,.maintenancePanel,.healthPanel,.productionPanel) .panelHead h2{
  color:#05070b!important;font-size:22px!important;font-weight:900!important;text-shadow:none!important;
}
:root[data-theme="light"] :where(.smartPanel,.maintenancePanel,.healthPanel,.productionPanel) .panelHead h2 svg{
  color:#126bd6!important;filter:none!important;stroke-width:2.8!important;
}
:root[data-theme="light"] :where(.smartPanel,.maintenancePanel,.healthPanel,.productionPanel) .panelHead p{
  color:#273344!important;font-size:12.5px!important;font-weight:700!important;
}
:root[data-theme="light"] :where(.smartPanel,.maintenancePanel,.healthPanel,.productionPanel) .round{
  border:2px solid #263548!important;background:#fff!important;color:#05070b!important;
}

/* 1. Smart dispatcher: remove the last black toolbar and give the empty state
   a useful, balanced white workspace instead of a long dead strip. */
:root[data-theme="light"] .smartPanel .smartToolbar{
  display:flex!important;align-items:center!important;justify-content:flex-start!important;flex-wrap:wrap!important;gap:9px!important;
  margin:0 0 12px!important;padding:12px!important;border:2px solid #263548!important;border-radius:12px!important;
  background:#f4f6f8!important;background-image:none!important;color:#05070b!important;box-shadow:none!important;clip-path:none!important;
}
:root[data-theme="light"] .smartPanel .smartToolbar :where(button,.button){
  min-height:42px!important;padding:9px 14px!important;border:2px solid #263548!important;border-radius:9px!important;
  background:#fff!important;background-image:none!important;color:#05070b!important;font-size:12.5px!important;font-weight:850!important;box-shadow:none!important;
}
:root[data-theme="light"] .smartPanel .smartToolbar .primary{
  border-color:#126bd6!important;background:#126bd6!important;color:#fff!important;
}
:root[data-theme="light"] .smartPanel .smartToolbar .autoOn{
  border-color:#197442!important;background:#ebf8ef!important;color:#125d35!important;
}
:root[data-theme="light"] .smartPanel .smartLayout{
  display:grid!important;grid-template-columns:minmax(0,1fr) 278px!important;gap:12px!important;align-items:stretch!important;
}
:root[data-theme="light"] .smartPanel .smartJobs{
  min-height:260px!important;display:grid!important;align-content:start!important;gap:9px!important;padding:12px!important;
  border:2px solid #263548!important;border-radius:12px!important;background:#fff!important;background-image:none!important;color:#05070b!important;box-shadow:none!important;clip-path:none!important;
}
:root[data-theme="light"] .smartPanel .smartJobs>article{
  border:2px solid #536174!important;border-radius:10px!important;background:#fff!important;background-image:none!important;color:#05070b!important;box-shadow:none!important;clip-path:none!important;
}
:root[data-theme="light"] .smartPanel .smartJobs :where(b,strong){color:#05070b!important;font-weight:850!important}
:root[data-theme="light"] .smartPanel .smartJobs :where(span,small,label){color:#273344!important;font-weight:680!important}
:root[data-theme="light"] .smartPanel .emptySmart{
  min-height:232px!important;display:grid!important;place-items:center!important;align-content:center!important;gap:9px!important;
  padding:30px!important;border:2px dashed #536174!important;border-radius:10px!important;background:#edf5ff!important;color:#273344!important;text-align:center!important;
}
:root[data-theme="light"] .smartPanel .emptySmart svg{width:34px!important;height:34px!important;color:#126bd6!important;stroke-width:2.4!important}
:root[data-theme="light"] .smartPanel .emptySmart b{font-size:18px!important;font-weight:900!important;color:#05070b!important}
:root[data-theme="light"] .smartPanel .emptySmart span{font-size:12.5px!important;font-weight:700!important;color:#273344!important}
:root[data-theme="light"] .smartPanel .compat{
  min-height:260px!important;padding:14px!important;border:2px solid #263548!important;border-radius:12px!important;
  background:#f4f6f8!important;background-image:none!important;color:#05070b!important;
}
:root[data-theme="light"] .smartPanel .compat h3{margin:0 0 10px!important;font-size:15px!important;font-weight:900!important}
:root[data-theme="light"] .smartPanel .compat>div{padding:10px 0!important;border-top:1px solid #aab4c1!important}
:root[data-theme="light"] .smartPanel .compat :where(b,span,small){display:block!important;color:#273344!important;font-size:11px!important;font-weight:700!important}
:root[data-theme="light"] .smartPanel .compat b{color:#05070b!important;font-size:12.5px!important;font-weight:850!important}
:root[data-theme="light"] .smartPanel .dispatchLog{
  min-height:48px!important;margin-top:12px!important;padding:10px 12px!important;border:2px solid #536174!important;border-radius:10px!important;
  background:#fff!important;background-image:none!important;color:#172033!important;box-shadow:none!important;
}

/* 2. Maintenance: the wrench is blue, never purple; every row and action has
   a dark two-pixel outline and text that stays black at normal zoom. */
:root[data-theme="light"] .maintenancePanel .panelHead h2 svg{color:#126bd6!important;filter:none!important}
:root[data-theme="light"] .maintenancePanel .maintenancePresets{gap:11px!important}
