import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import http from 'node:http';
import {createHash} from 'node:crypto';
import {build} from 'vite';

const root=path.resolve(import.meta.dirname,'..'),out=fs.mkdtempSync(path.join(os.tmpdir(),'kf-discovery-layout-'));
const option=name=>process.argv.find(value=>value.startsWith('--'+name+'='))?.slice(name.length+3);
const screenshotDir=process.env.KF_UI_SCREENSHOTS??option('screenshot-dir');
try{
  await build({root,logLevel:'warn',plugins:[{name:'mock-discovery-events',enforce:'pre',resolveId(source){if(source==='@tauri-apps/api/event')return'\0discovery-events'},load(id){if(id==='\0discovery-events')return'export const listen=(name,listener)=>globalThis.__discoveryListen(name,listener);'}}],build:{outDir:out,emptyOutDir:true,rollupOptions:{input:path.join(root,'ui-tests/discovery-layout.html')}}});
  if(process.argv.includes('--build-only')){console.log('Discovery layout fixture build OK: actual DiscoveryPanel, mocked native scan/events');process.exitCode=0}
  else{
    const{chromium}=await import(process.env.PLAYWRIGHT_MODULE_PATH??'playwright');
    const server=http.createServer((req,res)=>{const file=path.resolve(out,new URL(req.url,'http://localhost').pathname.slice(1));if(!file.startsWith(out+path.sep)||!fs.existsSync(file)){res.writeHead(404);res.end();return}res.setHeader('Content-Type',({'.js':'text/javascript','.css':'text/css','.html':'text/html'})[path.extname(file)]??'application/octet-stream');res.end(fs.readFileSync(file))});
    await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
    let browser;
    try{
      browser=await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_EXECUTABLE,args:['--no-sandbox','--disable-dev-shm-usage']});
      const url=`http://127.0.0.1:${server.address().port}/ui-tests/discovery-layout.html`,report=[];
      if(screenshotDir)fs.mkdirSync(screenshotDir,{recursive:true});
      const errors=[];
      let currentPage,currentCase={stage:'initialization'};
      const saveFailure=async error=>{
        if(error.discoveryDiagnosticsSaved)return;
        const directory=screenshotDir??path.join(os.tmpdir(),'kf-discovery-layout-failure-'+Date.now());
        fs.mkdirSync(directory,{recursive:true});
        const label=[currentCase.theme,currentCase.width,currentCase.height,currentCase.test].filter(Boolean).join('-')||'startup';
        const diagnostic={case:currentCase,error:String(error?.stack??error),geometry:error.discoveryGeometry,report,pageErrors:errors,files:{}};
        if(currentPage&&!currentPage.isClosed()){
          const imagePath=path.join(directory,label+'-failure.png'),htmlPath=path.join(directory,label+'-failure.html');
          try{await currentPage.screenshot({path:imagePath});diagnostic.files.screenshot=imagePath}catch(captureError){diagnostic.screenshotError=String(captureError)}
          try{fs.writeFileSync(htmlPath,await currentPage.content());diagnostic.files.dom=htmlPath}catch(captureError){diagnostic.domError=String(captureError)}
          try{diagnostic.domState=await currentPage.evaluate(()=>({viewport:{width:innerWidth,height:innerHeight},documentScroll:{top:document.scrollingElement.scrollTop,left:document.scrollingElement.scrollLeft},activeElement:document.activeElement?.outerHTML,calls:window.__calls,panels:[...document.querySelectorAll('.discoveryPanel,.discoveryPanelFoot,.discoveryAdvanced,.discoveryAdapters,.discoveryManualHost,.discoveryManualRange')].map(element=>({className:element.className,box:element.getBoundingClientRect().toJSON(),scrollTop:element.scrollTop,scrollLeft:element.scrollLeft,scrollHeight:element.scrollHeight,clientHeight:element.clientHeight,scrollWidth:element.scrollWidth,clientWidth:element.clientWidth,overflowX:getComputedStyle(element).overflowX,overflowY:getComputedStyle(element).overflowY}))}))}catch(captureError){diagnostic.domStateError=String(captureError)}
        }
        fs.writeFileSync(path.join(directory,'failure.json'),JSON.stringify(diagnostic,null,2));
        error.discoveryDiagnosticsSaved=true;
        console.error('Discovery layout failure diagnostics: '+path.join(directory,'failure.json'));
      };
      const open=async(page,theme)=>{
        page.on('pageerror',error=>errors.push(error.message));
        await page.goto(url+'?theme='+theme);
        await page.locator('.discoveryResults>article').nth(1).waitFor();
        await page.waitForFunction(()=>document.querySelector('.discoveryProgress b')?.textContent?.includes('508 / 508'));
        await page.locator('.discoveryAdvanced>summary').click();
      };
      const noHorizontalOverflow=async page=>{
        const failures=await page.locator('.discoveryPanel,.discoveryPanelHead,.discoveryPanelTitle,.discoveryProgress,.discoveryResults,.discoveryResults>article,.discoveryDeviceBody,.discoveryPanelFoot,.discoveryAdvanced,.discoveryAdapters,.discoveryManualHost,.discoveryManualRange').evaluateAll(elements=>elements.flatMap(element=>{const box=element.getBoundingClientRect();return box.left<-.5||box.right>innerWidth+.5||element.scrollWidth>element.clientWidth+2?[{className:element.className,left:box.left,right:box.right,scrollWidth:element.scrollWidth,clientWidth:element.clientWidth}]:[]}));
        assert.deepEqual(failures,[],'discovery modal horizontal overflow');
      };
      const reachable=async(locator,selector)=>{
        currentCase={...currentCase,selector};
        await locator.scrollIntoViewIfNeeded();
        const geometry=await locator.evaluate(element=>{
          const box=element.getBoundingClientRect(),viewport={left:0,top:0,right:innerWidth,bottom:innerHeight,width:innerWidth,height:innerHeight};
          let reachable=box.top>=-.5&&box.bottom<=innerHeight+.5;
          const ancestors=[],intersection={left:Math.max(0,box.left),top:Math.max(0,box.top),right:Math.min(innerWidth,box.right),bottom:Math.min(innerHeight,box.bottom)};
          for(let parent=element.parentElement;parent;parent=parent.parentElement){
            const style=getComputedStyle(parent);
