              const bounds=parent.getBoundingClientRect(),isDocumentScrollingElement=parent===document.scrollingElement;
              // A fixed modal can leave the root element's content rect at
              // height zero. Its overflow clips to the viewport, not that
              // empty content rect. Other ancestors keep their own bounds.
              const containmentBounds=isDocumentScrollingElement?viewport:bounds;
              const clientBounds=isDocumentScrollingElement?{left:0,top:0,right:parent.clientWidth,bottom:parent.clientHeight}:{left:bounds.left+parent.clientLeft,top:bounds.top+parent.clientTop,right:bounds.left+parent.clientLeft+parent.clientWidth,bottom:bounds.top+parent.clientTop+parent.clientHeight};
              const verticallyContains=box.top>=containmentBounds.top-.5&&box.bottom<=containmentBounds.bottom+.5;
              if(!verticallyContains)reachable=false;
