// Test printer/native boundary only. Listing, cache management, parsing,
// compatibility and launching remain the actual production modules.
export function createR126FilesNative(initialMode:string){
 let mode=initialMode;
 const cacheKey='production.printerFiles.printer-7';
 const nested='Детали/Серия №1/крепёж #1%.gcode';
 const header='; generated by OrcaSlicer\n; printer_model = Flashforge Adventurer 5M\n; nozzle_diameter = 0.4\n; filament_type = PLA\n; estimated printing time (normal mode) = 2m\nG90\nM82\nM104 S220\nM140 S60\nG1 X-80 Y-60 Z0.2 F1200\nG1 X70 Y50 E1\n';
 const originalCache={hashes:{retained:'Кеш/прежний.gcode'},projects:{'Кеш/прежний.gcode':'Старый проект'},folders:['Старый проект'],validations:{retained:{signature:'retained',checkedAt:123,report:{ok:false,issues:[{level:'error',code:'retained',message:'Сохранённая проверка'}]}}},files:[{path:'Кеш/прежний.gcode',size:999,modified:1700000000,metadata:{filename:'Кеш/прежний.gcode',filament_type:'PETG'}}],lastSyncedAt:123};
 const printed:string[]=[];
 const body=(value:unknown,status=200)=>({status,body:Array.from(new TextEncoder().encode(typeof value==='string'?value:JSON.stringify(value)))});
 const text=(path:string)=>{
  let value=header;
  if(mode==='outside')value+='G1 X110.1 Y0 E2\n';
  if(mode==='incompatible')value+='CX_PRINT_START\n';
  if(mode==='dangerous')value+='M112\n';
  if(mode==='wrong-model')value=value.replace('Flashforge Adventurer 5M','Creality K1 Max');
  return value+'; '+path+'\n';
 };
 const paths=()=>['rpc-array','rpc-envelope','fallback-404','fallback-405','fallback-method'].includes(mode)?['корпус.gcode',nested]:[nested];
 const rows=()=>paths().map((path,index)=>({path,size:new TextEncoder().encode(text(path)).length,modified:1700000000.25+index}));
 const failure=(prefix:string)=>{
  if(mode===prefix+'-timeout')throw new Error('request timeout: '+prefix);
  const match=mode.match(new RegExp('^'+prefix+'-(401|403|500|501|503|404)$'));
  return match?Number(match[1]):undefined;
 };
 return {
  cacheKey,originalCache,nested,
  state:()=>({mode,nested,printed:[...printed],expectedEntries:rows(),originalCache:structuredClone(originalCache)}),
  setMode(value:string){mode=value},
  dbReadFails:()=>mode==='db-read-error',dbWriteFails:()=>mode==='db-write-error',
  rpc(method:string,params:any){
   if(method==='server.files.list'){
    const status=failure('list');if(status)throw new Error('/server/files/list?root=gcodes HTTP '+status);
    if(mode.startsWith('fallback-')||mode.startsWith('directory-')||mode==='child-500'||mode==='partial-directory'||mode==='both-unavailable'){
     if(mode==='fallback-method')return {error:{code:-32601,message:'Method not found'}};
     throw new Error('/server/files/list?root=gcodes HTTP '+(mode==='fallback-405'?405:404));
    }
    if(mode==='partial-array')return [rows()[0],{size:100}];
    if(mode==='partial-envelope')return {result:[rows()[0]],partial:true};
    if(mode==='malformed-list')return {result:{files:rows()}};
    if(mode==='empty')return [];
    return mode==='rpc-envelope'?{result:rows()}:rows();
   }
   if(method==='printer.print.start'){
    printed.push(params.filename);
    return {status:{print_stats:{state:'printing',filename:params.filename,print_duration:0},virtual_sdcard:{is_active:true,progress:0}}};
   }
   throw new Error('Unexpected test file RPC '+method);
  },
  http(path:string){
   const url=new URL(path,'http://native-fixture');
   if(url.pathname==='/server/files/directory'){
    const status=failure('directory');if(status)return body({error:'fixture'},status);
    if(mode==='both-unavailable')return body({},404);
    const directory=url.searchParams.get('path')!;
    if(directory!=='gcodes'&&mode==='child-500')return body({error:'fixture child failed'},500);
    if(directory!=='gcodes'&&mode==='partial-directory')return body({result:{files:[{filename:'часть.gcode',size:20}]}});
    const prefix=directory==='gcodes'?'':directory.slice('gcodes/'.length)+'/';
    const files=rows().filter(row=>row.path.startsWith(prefix)&&!row.path.slice(prefix.length).includes('/')).map(({path,...row})=>({...row,filename:path.slice(prefix.length)}));
    const dirs=[...new Set(rows().filter(row=>row.path.startsWith(prefix)&&row.path.slice(prefix.length).includes('/')).map(row=>row.path.slice(prefix.length).split('/')[0]))].map(dirname=>({dirname}));
    return body({result:{files,dirs}});
   }
   if(url.pathname==='/server/files/metadata'){
    const status=failure('metadata');if(status)return body({},status);
    return body({result:{filename:url.searchParams.get('filename'),nozzle_diameter:.4,filament_type:'PLA',printer_model:'Flashforge Adventurer 5M',object_height:.2,estimated_time:120}});
   }
   if(url.pathname==='/server/files/thumbnails')return body({result:{thumbnails:[]}});
   if(url.pathname.startsWith('/server/files/gcodes/')){
    const status=failure('download');if(status)return body({},status);
    const relative=url.pathname.slice('/server/files/gcodes/'.length).split('/').map(decodeURIComponent).join('/');
    return body(text(relative));
   }
   return undefined;
  },
 };
}

